window.TADABBUR_ANBIYA = {"_meta":{"description":"تدبّرٌ مُسنَد لسورة الأنبياء (٢١)، سورةٌ مكّيّةٌ محورُها التوحيدُ والبعثُ والنبوّات؛ فيها ذكرُ جملةٍ من الأنبياء (إبراهيم، لوط، نوح، داود وسليمان، أيوب، يونس، زكريا، مريم) وتقريرُ وحدةِ رسالتهم وأنّ الله ربٌّ واحد. بُدئت بالحمد. كلُّ آيةٍ مغطّاةٍ تحمل وقفةً مُسنَدةً موسومة (ابن كثير/السعدي).","honesty":"لا نُقدّم شيئًا كإعجازٍ مُثبَت؛ المعنى منقولٌ بتصرّفٍ يسير من التفسيرين بإحالةٍ صريحة، ونصُّ الآيةِ لا يُكتَب هاهنا بأيدينا، بل يُنقَل عند القراءةِ من مصحفٍ محقَّقٍ مضبوط، صيانةً له من الخطأ."},"n":21,"name":"الأنبياء","total_ayahs":112,"audio":[19,22,30,35,47,69,83,87,90,107],"passages":[{"title":"اقترابُ الحساب وغفلةُ الناس","range":[1,6],"theme":"قربُ الحسابِ مع الغفلةِ والإعراض، ولهوُهم عند سماعِ الذكر","verses":[{"n":1,"reflection":{"text":"«اقترب للناس حسابهم وهم في غفلة معرضون»: قرُب للناسِ يومُ حسابهم (فكلُّ آتٍ قريب)، وهم في غفلةٍ عن الاستعدادِ له معرضون عن الاتّعاظ؛ ففي هذا التحذيرُ من الغفلةِ مع قربِ الحساب، وأنّ العمرَ قصيرٌ والموعدُ قريب؛ فانفض غفلتك واستعدَّ لحسابك، فما هو آتٍ قريبٌ وإن استبعدته النفوس.","source":"تفسير السعدي","grade":"ma'thur"},"names":["اقترب للناس حسابهم"],"heart_state":{"text":"طردُ الغفلةِ والاستعدادُ للحسابِ القريب."},"action":{"text":"أيقظ قلبك من الغفلةِ عن الآخرة، واستعدَّ لحسابك بالعملِ الصالحِ والتوبة؛ فحسابك قريبٌ وإن ظننته بعيدًا، ومن حاسب نفسه اليومَ خفّ حسابه غدًا."}},{"n":2,"reflection":{"text":"«ما يأتيهم من ذكر من ربهم محدث إلا استمعوه وهم يلعبون»: ما ينزل عليهم من قرآنٍ جديدٍ يذكّرهم إلا استمعوه استماعَ لاهٍ لاعبٍ لا مستفيد؛ ففي هذا ذمُّ الاستماعِ بلا تدبّرٍ ولا انتفاع، وأنّ اللعبَ يمنع الاتّعاظ؛ فاستمع للقرآنِ بجدٍّ وحضورِ قلب، لا باللهوِ واللعب، فالمقصودُ الاتّعاظُ لا مجردُ السماع.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاستماعُ للقرآنِ بجدٍّ وتدبّرٍ لا بلهو."},"action":{"text":"استمع للقرآنِ بقلبٍ حاضرٍ جادٍّ متدبّرٍ لتنتفع، ولا تستمع إليه لاهيًا لاعبًا كما يفعل الغافلون؛ فالعبرةُ بأثرِ الذكرِ في القلبِ والعمل، لا بمجرّدِ وصولِ الصوتِ للأذن."}},{"n":3,"reflection":{"text":"«لاهية قلوبهم وأسروا النجوى الذين ظلموا هل هذا إلا بشر مثلكم أفتأتون السحر وأنتم تبصرون»: قلوبهم مشغولةٌ لاهيةٌ عن الحقّ، وتناجى الظالمون سرًّا: ما هذا إلا بشرٌ مثلكم فكيف يكون رسولًا؟ أتحضرون السحرَ (يعنون القرآن) وأنتم تعلمون أنه سحر؟ ففي هذا أنّ لهوَ القلبِ يقود إلى ردِّ الحقِّ بالشبهات، وأنّ الطعنَ في بشريّةِ الرسولِ شبهةٌ قديمة؛ فطهّر قلبك من اللهو ليقبل الحقّ، ولا تردَّ الحقَّ بشبهاتٍ واهية.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"تطهيرُ القلبِ من اللهوِ لقبولِ الحقّ."},"action":{"text":"طهّر قلبك من اللهوِ والانشغالِ عن الحقّ، فلهوُ القلبِ يحجبه عن قبولِ الحقِّ ويدفعه لردّه بالشبهات؛ فأقبل على الحقِّ بقلبٍ فارغٍ له، ولا تردّه بحججٍ واهيةٍ كفعلِ الظالمين."}},{"n":4,"reflection":{"text":"«قال ربي يعلم القول في السماء والأرض وهو السميع العليم»: قال النبيُّ ﷺ: ربّي يعلم كلَّ قولٍ في السماءِ والأرض سرَّه وعلنه، وهو السميعُ لكلِّ مسموع، العليمُ بكلِّ معلوم؛ ففي هذا أنّ الله يعلم نجوى الظالمين وما يسرّون، وأنّ علمه محيط؛ فراقب الله في سرِّك وعلنك، فهو السميعُ العليمُ الذي لا يخفى عليه قولٌ ولا نجوى.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["السميع العليم"],"heart_state":{"text":"مراقبةُ الله السميعِ العليمِ في السرِّ والعلن."},"action":{"text":"راقب الله في أقوالك سرِّها وعلنها، فهو يعلم القولَ في السماءِ والأرضِ ويسمع كلَّ نجوى؛ فاحفظ لسانك ونجواك عن كلِّ باطل، واستحضر أنه السميعُ العليمُ لا يغيب عنه شيء."}},{"n":5,"reflection":{"text":"«بل قالوا أضغاث أحلام بل افتراه بل هو شاعر فليأتنا بآية كما أرسل الأولون»: بل تحيّر المكذّبون في وصفِ القرآن: قالوا أحلامٌ مختلطة، بل اختلقه، بل هو شعر، فليأتنا بمعجزةٍ حسّيّةٍ كما أُرسِل الأنبياءُ الأوّلون؛ ففي هذا اضطرابُ المبطلين وتناقضُ أقوالهم، وأنّ المعاندَ يتخبّط في ردِّ الحقّ؛ فتأمّل تناقضَ المبطلين دليلًا على بطلانهم، والزم الحقَّ الواحدَ الثابت، فالباطلُ متناقضٌ مضطرب.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاعتبارُ بتناقضِ المبطلين، ولزومُ الحقِّ الثابت."},"action":{"text":"تأمّل كيف يتناقض المبطلون ويتخبّطون في وصفِ الحقِّ وردّه، فذلك دليلُ بطلانهم؛ والزم أنت الحقَّ الواحدَ الثابتَ الذي لا اضطرابَ فيه، فالحقُّ واحدٌ والباطلُ شعبٌ متناقضة."}},{"n":6,"reflection":{"text":"«ما آمنت قبلهم من قرية أهلكناها أفهم يؤمنون»: ما آمنت قبل هؤلاء أمّةٌ اقترحت الآياتِ ثم أهلكناها لمّا لم تؤمن بعد مجيئها، أفهؤلاء يؤمنون لو جاءتهم الآيةُ المقترحة؟ لا؛ ففي هذا أنّ اقتراحَ الآياتِ تعنّتٌ لا يعقبه إيمان، وأنّ من لم ينفعه البيانُ لم تنفعه الآية؛ فلا تعلّق إيمانك بالآياتِ المقترحة، بل بالبيّناتِ القائمة، فالمعاندُ لا يؤمن ولو رأى كلَّ آية.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"عدمُ تعليقِ الإيمانِ باقتراحِ الآياتِ الحسّية."},"action":{"text":"لا تعلّق إيمانك أو قبولك للحقِّ باقتراحِ آياتٍ حسّيّةٍ بعد قيامِ البراهين، فذلك تعنّتٌ لا يعقبه إيمان؛ فاكتفِ بما أقام الله من الحجج، وآمن بالبيّناتِ القائمةِ لا بالمقترحات."}}]},{"title":"بشريةُ الرسلِ وإهلاكُ الظالمين","range":[7,15],"theme":"أنّ الرسلَ بشرٌ يوحى إليهم، وإنزالُ الذكر، وقصمُ القرى الظالمة","verses":[{"n":7,"reflection":{"text":"«وما أرسلنا قبلك إلا رجالا نوحي إليهم فاسألوا أهل الذكر إن كنتم لا تعلمون»، وما أرسلنا قبلك يا محمد إلا رجالًا من البشرِ نوحي إليهم لا ملائكة، فاسألوا أهلَ العلمِ بالكتبِ السابقةِ إن كنتم لا تعلمون؛ ففي هذا الردُّ على من استنكر بشريّةَ الرسول، والأمرُ بالرجوعِ إلى أهلِ العلمِ فيما يُجهَل؛ فاسأل أهلَ العلمِ فيما لا تعلم، فردُّ الجاهلِ إلى العالمِ سبيلُ الهدى، ولا تفتِ بغيرِ علم.","source":"تفسير السعدي","grade":"ma'thur"},"names":["فاسألوا أهل الذكر"],"heart_state":{"text":"الرجوعُ إلى أهلِ العلمِ فيما يُجهَل."},"action":{"text":"إذا جهلت أمرًا من أمرِ الدينِ فاسأل عنه أهلَ العلمِ الراسخين، ولا تقل بغيرِ علمٍ ولا تُفتِ بجهل؛ فقد أمر الله بسؤالِ أهلِ الذكر، فردُّ ما تجهله إلى العلماءِ من الهدى."}},{"n":8,"reflection":{"text":"«وما جعلناهم جسدا لا يأكلون الطعام وما كانوا خالدين»، وما جعلنا الرسلَ أجسادًا لا يأكلون الطعامَ كالملائكة، بل كانوا بشرًا يأكلون، وما كانوا مخلّدين في الدنيا بل يموتون؛ ففي هذا إثباتُ بشريّةِ الرسلِ في حاجتهم للطعامِ وموتهم، وأنّ ذلك لا ينقص من رسالتهم؛ فلا تستنكر أن يكون الرسولُ بشرًا يأكل ويموت، فكمالُه في وحيه ورسالته لا في مفارقةِ طبعِ البشر.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"قبولُ بشريّةِ الرسلِ وأنها لا تنقص رسالتهم."},"action":{"text":"اعلم أنّ الأنبياءَ بشرٌ يأكلون ويموتون، وأنّ بشريّتهم لا تنقص من رسالتهم شيئًا؛ فلا تستنكر الحقَّ لأنّ حامله بشرٌ مثلك، فالعبرةُ بصدقِ ما جاء به لا بمفارقةِ الطبع."}},{"n":9,"reflection":{"text":"«ثم صدقناهم الوعد فأنجيناهم ومن نشاء وأهلكنا المسرفين»: ثم حقّقنا للرسلِ وعدنا فأنجيناهم ومن نشاء من أتباعهم المؤمنين، وأهلكنا المسرفين المتجاوزين حدودَ الله بالكفرِ والتكذيب؛ ففي هذا أنّ وعدَ الله لرسله بالنجاةِ حقّ، وأنّ عاقبةَ المسرفين الهلاك؛ فثق بوعدِ الله لأهلِ الحقِّ بالنجاة، واحذر الإسرافَ في المعاصي فإنه سببُ الهلاك.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الثقةُ بوعدِ النجاةِ لأهلِ الحقّ، والحذرُ من الإسراف."},"action":{"text":"ثق بأنّ الله يصدق وعده لأهلِ الحقِّ بالنجاةِ والنصر، واحذر الإسرافَ في المعصيةِ ومجاوزةَ حدودِ الله فإنه سببُ الهلاك؛ فكن مع الصادقين المؤمنين تنجُ، ولا تكن مع المسرفين فتهلك."},"qadiyya":{"title":"قضيّةُ الشبهة المتكرّرة: ردٌّ يُلزم الخصمَ بما يُقرّ به هو","question":"قال المكذّبون للنبيِّ ﷺ: **هلّا كان ملَكًا لا يأكل ولا يمشي في الأسواق؟ وهلّا كان خالدًا لا يموت؟** **فإن كان بشرًا يأكل ويموت، فليس برسول.**\nوهي شبهةٌ لها ظاهرٌ معقول: **أنّ الرسالة أمرٌ عظيم، فينبغي أن يحملها كائنٌ عظيم.**\nفالقضيّة: **بمَ أجاب القرآنُ عن هذه الشبهة؟ وهل ردَّها بدعوى أم ألزمهم بما لا يستطيعون إنكاره؟** ثمّ: **لماذا يقول السعديُّ إنّ هذه الشبهةَ «ما زالت» قائمة؟**","background":"ولا يُفهم وجهُ الإلزام حتى نعرف عن القوم أمرًا واحدًا:\n**أنّ مشركي قريش لم يكونوا ينكرون النبوّةَ من أصلها.**\n**بل كانوا يُقرّون بإبراهيمَ عليه السلام نبيًّا**، ويفتخرون بأنّهم من ولده، **ويزعمون أنّهم على دينه وملّته**؛ فمنه ورثوا البيتَ والحجَّ وبعضَ المناسك.\n**فالخصمُ إذًا مُقرٌّ بأصل النبوّة، منكرٌ لهذا النبيِّ بعينه.**\n**وهذا يفتح على المحاجّ بابًا**: **أن يأخذه بما أقرّ به.**","what_happened":"**بيّن السعديُّ الشبهةَ أوّلًا بلفظها**: «**هذا جوابٌ لشبه المكذّبين للرسول القائلين: هلّا كان ملَكًا، لا يحتاج إلى طعامٍ وشراب، وتصرّفٍ في الأسواق، وهلّا كان خالدًا؟ فإذا لم يكن كذلك، دلّ على أنّه ليس برسول**».\n**ثمّ نبّه إلى أنّها ليست شبهةَ قومٍ بعينهم**: «**وهذه الشبهُ ما زالت في قلوب المكذّبين للرسل، تشابهوا في الكفر، فتشابهت أقوالُهم**».\n**فربط تشابهَ الأقوال بتشابه القلوب**، لا بتناقل الكلام.\n**ثمّ ساق وجهَ الجواب، وهو إلزام**: أنّ هؤلاء «**المقرّين بإثبات الرسل قبله، ولو لم يكن إلّا إبراهيمُ عليه السلام، الذي قد أقرّ بنبوّته جميعُ الطوائف، والمشركون يزعمون أنّهم على دينه وملّته**».\n**ثمّ قرّر أنّ الرسل قبله كانوا بشرًا**، «**يأكلون الطعام، ويمشون في الأسواق، وتطرأ عليهم العوارضُ البشريّة، من الموت وغيره**»، **وأنّ الله صدّقهم وعدَه فنجّاهم وأهلك المكذّبين.**\n**ثمّ ألزمهم**: «**فما بالُ محمّدٍ صلّى الله عليه وسلّم، تُقام الشبهُ الباطلةُ على إنكار رسالته، وهي موجودةٌ في إخوانه المرسلين، الذين يُقرّ بهم المكذّبون لمحمّد؟**».\n**ثمّ ختم بالحكم على الحجّة نفسِها**: «**فهذا إلزامٌ لهم في غاية الوضوح**».","the_verdict":"**فالحاصلُ أنّ الشبهة لم تُردّ باستنكار، بل بأنّها تنقض ما يُقرّ به قائلوها.**\n**وهذا هو «الإلزام»**: أن تأخذ خصمَك بلازم قوله هو، **فتُريه أنّه لو صحّ ما قال لبطل ما يعتقده.**\nفالقومُ يقولون: **البشريّةُ تمنع الرسالة.**\nوهم يقولون: **إبراهيمُ رسول.**\nوإبراهيمُ كان بشرًا يأكل ويموت.\n**فإمّا أن تسقط المقدّمةُ الأولى، وإمّا أن يُنكروا إبراهيم.** **ولن يفعلوا الثاني لأنّ عليه مدارَ شرفهم في العرب.**\n**⭐ وقوّةُ هذا الردّ أنّه لا يحتاج إلى أن يُسلّم الخصمُ بشيءٍ جديد.** **فأنت لا تطلب منه أن يصدّقك؛ إنّما تطلب منه أن يكون متّسقًا مع نفسه.** **وهذا أثقلُ عليه من كلِّ برهانٍ خارجيّ، لأنّه لا يستطيع أن يردّه بأن يقول: هذا رأيك.**\n**وأمّا قولُ السعديّ «وهذه الشبهُ ما زالت في قلوب المكذّبين للرسل، تشابهوا في الكفر، فتشابهت أقوالُهم» ففيه معنًى أعمقُ من التاريخ.**\n**فهو لم يقل: تناقلوا الأقوال. قال: تشابهت القلوبُ فتشابهت الأقوال.** **أي أنّ الشبهةَ ليست موروثةً بالتلقّي، بل هي مولودةٌ من حالٍ واحدةٍ تتكرّر.** **ولهذا تجدها تُقال في كلِّ زمانٍ ممّن لم يقرأ ما قالته قريش.**\n**وفيه فائدةٌ عمليّة**: **أنّ الشبهة إذا تكرّرت فليس علاجُها ابتكارَ جوابٍ جديد**، بل **الرجوعَ إلى الجواب القرآنيّ الذي أُجيبت به أوّلَ مرّة.**","for_you":"**فأمّا الذي تخرج به فثلاثة:**\n**الأوّل، وهو أنفعُ ما في الباب: ابحثْ عمّا يُقرّ به مخالفُك قبل أن تبحث عمّا تردّ به عليه.** **فالحجّةُ المبنيّةُ على إقراره تُلزمه، والمبنيّةُ على إقرارك تُخبره.** **وأكثرُ المناظرات تفشل لأنّ كلَّ واحدٍ يحتجّ بما يُسلّم به هو ولا يُسلّم به صاحبُه.**\n**والثاني: إذا سمعتَ شبهةً فلا تسألْ عمّن قالها، بل عن الموضع الذي قيلت فيه أوّلَ مرّة.** **فإنّ أكثر الشبه المعاصرة لها أصلٌ في القرآن مذكورٌ مع جوابه.** **والجوابُ الذي أنزله اللهُ أثبتُ من جوابٍ نبتكره.**\n**والثالث: تأمّلْ في نفسك حين تردّ حقًّا.** **فقد بيّن السعديُّ أنّ الأقوال تتشابه لأنّ القلوب تتشابه.** **فإذا وجدتَ نفسَك تردّ أمرًا بحجّةٍ لو أُعملت في غيره لهدمت ما تعتقده، فاعلم أنّ الحجّةَ ليست هي السبب؛ إنّما هي ثوبٌ لبسه شيءٌ آخرُ في قلبك.** **وهذا هو موضعُ الفحص، لا الحجّة.**","grade":"ma'thur","source":"بيانُ السعديّ للشبهة («هذا جواب لشبه المكذبين للرسول القائلين: هلا كان ملكا، لا يحتاج إلى طعام وشراب، وتصرف في الأسواق، وهلا كان خالدا؟ فإذا لم يكن كذلك، دل على أنه ليس برسول»)، وقولُه في تكرّرها («وهذه الشبه ما زالت في قلوب المكذبين للرسل، تشابهوا في الكفر، فتشابهت أقوالهم»)، وموضعُ الإلزام («ولو لم يكن إلا إبراهيم عليه السلام، الذي قد أقر بنبوته جميع الطوائف، والمشركون يزعمون أنهم على دينه وملته»)، وصياغتُه للإلزام («فما بال محمد صلى الله عليه وسلم، تقام الشبه الباطلة على إنكار رسالته، وهي موجودة في إخوانه المرسلين، الذين يقر بهم المكذبون لمحمد؟»)، وحكمُه («فهذا إلزام لهم في غاية الوضوح»): كلُّها بنصّها في تفسير السعديّ (٢١:٩).","honesty":"وممّا يجب أن يُقال:\n**تحليلُنا لبنية الإلزام في ثلاث مقدّماتٍ صياغةٌ منّا**، والمعاني كلُّها من كلام السعديّ بألفاظه؛ **وهو لم يرتّبها هكذا.**\n**وأمّا قولُنا إنّ قريشًا ورثت البيتَ والحجَّ وبعضَ المناسك من إبراهيم فمعلومٌ من السيرة، ولم ننقله عن أحدٍ من الستّة في هذا الموضع بلفظه؛ والذي ننسبه للسعديّ قولُه إنّهم «يزعمون أنهم على دينه وملته».**\n**وأمّا استنباطُنا من قوله «تشابهوا في الكفر، فتشابهت أقوالهم» أنّ الشبهة مولودةٌ من حالٍ لا موروثةٌ بالتلقّي، فلازمٌ استخرجناه من لفظه؛ ومن رأى أنّا وسّعنا فليردّه.**\n**وأمّا قولُنا إنّ أكثر الشبه المعاصرة لها أصلٌ في القرآن فوصفٌ عامٌّ منّا، لا إحصاءَ عندنا به.**"}},{"n":10,"reflection":{"text":"«لقد أنزلنا إليكم كتابا فيه ذكركم أفلا تعقلون»: لقد أنزلنا إليكم قرآنًا فيه شرفكم وذكركم وعزّكم إن عملتم به، أفلا تعقلون فتنتفعوا به؟ ففي هذا أنّ في القرآنِ شرفَ الأمّةِ وعزّها، وأنّ العقلَ يقتضي الانتفاعَ به؛ فاعمل بالقرآنِ ليكون لك شرفًا وعزًّا، فبه رفعةُ من تمسّك به، وذلُّ من أعرض عنه.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["فيه ذكركم"],"heart_state":{"text":"طلبُ الشرفِ والعزِّ بالعملِ بالقرآن."},"action":{"text":"اعمل بالقرآنِ تلاوةً وتدبّرًا وتطبيقًا، فبه شرفك وعزّك في الدنيا والآخرة؛ فمن رفعه القرآنُ ارتفع، ومن أعرض عنه ذلَّ، فتمسّك به يكن لك ذكرًا وعزًّا بين الناسِ وعند الله."}},{"n":11,"reflection":{"text":"«وكم قصمنا من قرية كانت ظالمة وأنشأنا بعدها قوما آخرين»، وكثيرٌ من القرى الظالمةِ أهلكناها إهلاكًا مستأصِلًا، وأنشأنا بعدها أقوامًا آخرين مكانهم؛ ففي هذا أنّ الظلمَ سببُ استئصالِ الأمم، وأنّ الله يستبدل بالظالمين غيرهم؛ فاحذر الظلمَ فهو مهلكةُ الأممِ والأفراد، واعلم أنّ الله غنيٌّ عن الظالمين يستبدل بهم من يطيعه.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من الظلمِ الذي هو سببُ استئصالِ الأمم."},"action":{"text":"احذر الظلمَ في حقِّ الله وحقِّ الخلق، فهو سببُ هلاكِ الأممِ واستئصالها؛ واعلم أنّ الله غنيٌّ عنك، إن ظلمت استبدل بك غيرك؛ فالزم العدلَ تدُم لك النعمةُ وتُحفَظ."}},{"n":12,"reflection":{"text":"«فلما أحسوا بأسنا إذا هم منها يركضون»: فلما أحسّ الظالمون بعذابنا نازلًا أخذوا يهربون مسرعين من قريتهم؛ ففي هذا أنّ الهربَ من عذابِ الله لا ينفع عند نزوله، وأنّ الندمَ حين المعاينةِ لا يجدي؛ فلا تنتظر معاينةَ العذابِ لتفرَّ منه، فالفرارُ حينئذٍ لا ينجّي، وإنما النجاةُ بالتوبةِ قبل نزولِ البأس.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"المبادرةُ بالتوبةِ قبل نزولِ البأسِ حيث لا ينفع الفرار."},"action":{"text":"بادر بالتوبةِ والرجوعِ إلى الله قبل نزولِ عذابه، فإنّ الفرارَ منه عند معاينته لا ينجّي؛ فلا تسوّف حتى تعاين البأسَ فتهرب حيث لا مهرب، بل تُب اليومَ وأنت في مهلة."}},{"n":13,"reflection":{"text":"«لا تركضوا وارجعوا إلى ما أترفتم فيه ومساكنكم لعلكم تسألون»: يقال لهم توبيخًا: لا تهربوا وارجعوا إلى ما كنتم فيه من النعيمِ والترفِ ومساكنكم لعلّكم تُسألون عن أموركم (كعادتكم في الدنيا)؛ ففي هذا تهكّمٌ بالظالمين وتوبيخٌ لهم على ترفهم الذي أبطرهم، وأنّ الترفَ يورث الغفلةَ والطغيان؛ فاحذر أن يُبطِرك الترفُ والنعيمُ فينسيك الآخرة، واشكر النعمةَ بالطاعة.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من أن يُبطِر الترفُ ويُنسي الآخرة."},"action":{"text":"احذر أن يُبطِرك النعيمُ والترفُ فينسيك ربّك وآخرتك كما أبطر الظالمين، فاشكر نعمتك بطاعةِ المُنعِمِ لا بالطغيان؛ فكم من ترفٍ أورث غفلةً، ونعمةٍ صارت وبالًا بكفرها."}},{"n":14,"reflection":{"text":"«قالوا يا ويلنا إنا كنا ظالمين»: قال الظالمون عند معاينةِ العذاب: يا هلاكَنا إنا كنا ظالمين بكفرنا وتكذيبنا؛ ففي هذا اعترافُهم بظلمهم حين لا ينفع الاعتراف، وأنّ الإقرارَ بعد فواتِ الأوانِ لا يجدي؛ فبادر بالاعترافِ بذنبك والتوبةِ منه في زمنِ المهلة، فالاعترافُ النافعُ ما كان قبل نزولِ العذاب.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"المبادرةُ بالاعترافِ بالذنبِ والتوبةِ في زمنِ المهلة."},"action":{"text":"بادر بالاعترافِ بذنبك والتوبةِ منه ما دمت في مهلةِ الحياة، فالاعترافُ بعد معاينةِ العذابِ لا ينفع؛ فلا تؤخّر التوبةَ حتى تقول «يا ويلنا إنا كنا ظالمين» حين لا يُقبَل."}},{"n":15,"reflection":{"text":"«فما زالت تلك دعواهم حتى جعلناهم حصيدا خامدين»: فما زالوا يردّدون هذا الاعترافَ والدعاءَ بالويلِ حتى جعلناهم كالزرعِ المحصودِ الميّتِ الهامدِ لا حركةَ فيهم؛ ففي هذا سرعةُ زوالِ الظالمين وانطفاءِ شأنهم، وأنّ العزَّ الظاهرَ يصير إلى خمود؛ فلا يغرّنك عزُّ الظالمين وقوّتُهم، فمصيرهم إلى حصدٍ وخمودٍ سريع، والعاقبةُ للمتّقين.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"عدمُ الاغترارِ بعزِّ الظالمين وسرعةِ زوالهم."},"action":{"text":"لا يغرّنك ما للظالمين من قوّةٍ وعزٍّ ظاهر، فإنّ مصيرهم إلى الهلاكِ والخمودِ السريع كالزرعِ المحصود؛ فاثبت على الحقِّ ولو قلّ أهله، فالعاقبةُ للمتّقين لا للطاغين."}}]},{"title":"جِدّيّةُ الخلقِ ودمغُ الحقِّ للباطل","range":[16,20],"theme":"أنّ الخلقَ بحقٍّ لا لعب، ودمغُ الحقِّ الباطل، وتسبيحُ الملائكةِ الدائم","verses":[{"n":16,"reflection":{"text":"«وما خلقنا السماء والأرض وما بينهما لاعبين»، وما خلقنا السماءَ والأرضَ وما بينهما عبثًا ولا لعبًا، بل لحكمةٍ عظيمةٍ من عبادةٍ وابتلاءٍ وجزاء؛ ففي هذا أنّ الكونَ خُلِق بحقٍّ وحكمة، وأنّ إنكارَ البعثِ يجعل الخلقَ عبثًا؛ فتأمّل أنّ خلقك لغايةٍ لا عبثًا، فاعمل لتلك الغايةِ التي خُلِقت لها، وهي عبادةُ الله.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"استحضارُ أنّ الخلقَ لحكمةٍ لا عبثًا، والعملُ لغايته."},"action":{"text":"استحضر أنّ الله ما خلق الكونَ ولا خلقك عبثًا، بل لحكمةٍ هي عبادته وابتلاؤك ثم جزاؤك؛ فاعمل لهذه الغايةِ التي خُلِقت لها، ولا تعش عبثًا كأنك لم تُخلَق لشيء."}},{"n":17,"reflection":{"text":"«لو أردنا أن نتخذ لهوا لاتخذناه من لدنا إن كنا فاعلين»: لو أردنا أن نتّخذ لهوًا (زوجةً أو ولدًا كما يزعمون) لاتّخذناه من عندنا، لكنا لا نفعل ذلك لتنزّهنا عنه؛ ففي هذا تنزيهُ الله عن اللهوِ والولدِ والصاحبة، وأنه منزّهٌ عن كلِّ نقص؛ فنزّه ربّك عن كلِّ ما لا يليق به، واعبده وحده الكاملَ في ذاته وصفاته.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"تنزيهُ الله عن اللهوِ وكلِّ نقصٍ لا يليق به."},"action":{"text":"نزّه الله عن اللهوِ والولدِ والصاحبةِ وكلِّ نقصٍ نسبه إليه الجاهلون، وأثبت له الكمالَ المطلق؛ فمن عرف تنزّهَ الله عبده وحده وأجلّه، ولم ينسب إليه ما لا يليق بجلاله."}},{"n":18,"reflection":{"text":"«بل نقذف بالحق على الباطل فيدمغه فإذا هو زاهق ولكم الويل مما تصفون»: بل نرمي بالحقِّ على الباطلِ فيمحقه ويكسره فإذا الباطلُ ذاهبٌ مضمحلّ، ولكم الهلاكُ ممّا تصفون الله به من الكذب؛ ففي هذا أنّ الحقَّ يدمغ الباطلَ ويزهقه، وأنّ العاقبةَ للحقّ؛ فانصر الحقَّ واثقًا بأنه يمحق الباطل، فما ثبت باطلٌ أمام حقّ، والعاقبةُ للحقِّ وإن تأخّرت.","source":"تفسير السعدي","grade":"ma'thur"},"names":["نقذف بالحق على الباطل فيدمغه"],"heart_state":{"text":"الثقةُ بأنّ الحقَّ يدمغ الباطلَ ويزهقه."},"action":{"text":"انصر الحقَّ وابسطه واثقًا بأنه يدمغ الباطلَ فيزهقه، فما ثبت باطلٌ في وجهِ حقٍّ يُقذَف عليه؛ فلا يهولنّك تعاظمُ الباطلِ حينًا، فالعاقبةُ للحقِّ وأهله لا محالة."}},{"n":19,"reflection":{"text":"«وله من في السماوات والأرض ومن عنده لا يستكبرون عن عبادته ولا يستحسرون»، ولله وحده مِلكًا وعبيدًا كلُّ من في السماواتِ والأرض، والملائكةُ الذين عنده لا يتكبّرون عن عبادته ولا يتعبون منها؛ ففي هذا أنّ العبوديةَ تشمل الخلقَ كلَّهم، وأنّ الملائكةَ قدوةٌ في التواضعِ ودوامِ العبادةِ بلا مللٍ ولا كِبر؛ فاقتدِ بالملائكةِ في التواضعِ لعبادةِ الله وعدمِ الملل، فالعبادةُ شرفٌ لا كُلفةَ تُملّ.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاقتداءُ بالملائكةِ في التواضعِ ودوامِ العبادة."},"action":{"text":"اقتدِ بالملائكةِ الذين لا يستكبرون عن عبادةِ الله ولا يملّون منها، فتواضع لعبادةِ ربّك ولا تستثقلها؛ فمن استشعر شرفَ العبوديةِ لم يتكبّر عنها ولم يفتر، بل أنِس بها ولزمها."}},{"n":20,"reflection":{"text":"«يسبحون الليل والنهار لا يفترون»: الملائكةُ يسبّحون الله في الليلِ والنهارِ دائمًا لا يضعفون ولا ينقطعون؛ ففي هذا كمالُ عبادةِ الملائكةِ ودوامُها، وأنّ التسبيحَ عبادةٌ لا تنقطع؛ فأكثر من تسبيحِ الله وذكرِه في ليلك ونهارك، واقتدِ بالملائكةِ في المداومةِ على الذكرِ بلا فتور.","source":"تفسير السعدي","grade":"ma'thur"},"names":["يسبحون الليل والنهار لا يفترون"],"heart_state":{"text":"المداومةُ على التسبيحِ والذكرِ بلا فتور."},"action":{"text":"اجعل لسانك رطبًا بتسبيحِ الله وذكرِه في ليلك ونهارك، واقتدِ بالملائكةِ في دوامِ التسبيحِ بلا مللٍ ولا فتور؛ فالذكرُ خفيفٌ على اللسانِ ثقيلٌ في الميزان، لا ينقطع فضله."}}]},{"title":"براهينُ التوحيدِ وتنزيهُ الله","range":[21,29],"theme":"دليلُ التمانع، وأنّ الله لا يُسأل، ووحدةُ دعوةِ الرسلِ للتوحيد","verses":[{"n":21,"reflection":{"text":"«أم اتخذوا آلهة من الأرض هم ينشرون»: بل أاتّخذ المشركون آلهةً من الأرض (أصنامًا) هي تحيي الموتى وتبعثهم؟ لا تقدر على ذلك؛ ففي هذا إبطالُ عبادةِ ما لا يقدر على الإحياءِ والبعث، وأنّ المعبودَ الحقَّ من يحيي ويميت؛ فلا تعبد إلا من يقدر على الإحياءِ والبعث، وهو الله وحده، فما سواه عاجزٌ لا يستحقُّ العبادة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"إفرادُ الله بالعبادةِ لأنه وحده المحيي المميت."},"action":{"text":"لا تعبد ولا ترجُ إلا الله الذي يحيي ويميت ويبعث، فما سواه من معبوداتٍ عاجزٌ لا يملك إحياءً ولا بعثًا؛ فأخلص عبادتك للقادرِ وحده، ولا تصرفها لعاجزٍ مثلك أو دونك."}},{"n":22,"reflection":{"text":"«لو كان فيهما آلهة إلا الله لفسدتا فسبحان الله رب العرش عما يصفون»: لو كان في السماواتِ والأرضِ آلهةٌ سوى الله لاختلّ نظامهما وفسدتا (لتنازعِ الآلهة)، فتنزّه الله ربُّ العرشِ عمّا يصفه به المشركون؛ ففي هذا دليلُ التمانعِ العقليُّ على وحدانيّةِ الله (فانتظامُ الكونِ دليلُ وحدةِ مدبّره)؛ فتأمّل انتظامَ الكونِ دليلًا على وحدةِ الله، ونزّهه عن الشريك.","source":"تفسير السعدي","grade":"ma'thur"},"names":["رب العرش","لفسدتا"],"heart_state":{"text":"الاستدلالُ بانتظامِ الكونِ على وحدانيّةِ الله."},"action":{"text":"تأمّل انتظامَ الكونِ واتّساقَ تدبيرِه دليلًا قاطعًا على وحدةِ خالقِه ومدبّره، فلو تعدّد الآلهةُ لفسد؛ فوحّد الله في ربوبيّته وألوهيّته، ونزّهه عن كلِّ شريكٍ يصفونه به."}},{"n":23,"reflection":{"text":"«لا يسأل عما يفعل وهم يسألون»: لا يُسأل الله عمّا يفعل لكمالِ حكمته وعدله وعلوِّ ربوبيّته، والخلقُ يُسألون عن أعمالهم لأنهم عبيدٌ مربوبون؛ ففي هذا إثباتُ كمالِ حكمةِ الله وتفرّدِه بالربوبيّة، وأنّ العبدَ محاسَبٌ؛ فسلّم لله في أفعاله وأقداره فكلُّها حكمة، واستعدَّ لأنك مسؤولٌ عن عملك محاسَبٌ عليه.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"التسليمُ لحكمةِ الله، والاستعدادُ للمساءلة."},"action":{"text":"سلّم لله في كلِّ ما يقضيه ويفعله، فهو الحكيمُ الذي لا يُسأل عن فعله لكمالِ حكمته؛ واستعدَّ لأنك أنت المسؤولُ المحاسَبُ عن عملك، فراقب الله فيما تفعل، وارضَ بما يقضي."}},{"n":24,"reflection":{"text":"«أم اتخذوا من دونه آلهة قل هاتوا برهانكم هذا ذكر من معي وذكر من قبلي بل أكثرهم لا يعلمون الحق فهم معرضون»: بل أاتّخذوا من دون الله آلهة؟ قل: هاتوا حجّتكم على ذلك، هذا القرآنُ ذكرُ أمّتي والكتبُ السابقةُ ذكرُ من قبلي، كلُّها على التوحيد، بل أكثرهم يجهلون الحقَّ فهم عنه معرضون؛ ففي هذا أنّ الشركَ لا برهانَ عليه، وأنّ الرسالاتِ كلَّها على التوحيد؛ فاطلب البرهانَ على كلِّ معتقَد، ولا تتّبع ما لا دليلَ عليه، فالتوحيدُ دعوةُ الرسلِ جميعًا.","source":"تفسير السعدي","grade":"ma'thur"},"names":["هاتوا برهانكم"],"heart_state":{"text":"طلبُ البرهانِ على المعتقَد، ولزومُ التوحيدِ دعوةَ الرسل."},"action":{"text":"لا تعتقد ولا تعبد إلا بدليلٍ وبرهان، فالشركُ لا حجّةَ له؛ والزم التوحيدَ الذي هو دعوةُ الرسلِ جميعًا في كلِّ الكتب؛ فما وافق الوحيَ فاتبعه، وما خالفه فاطرحه ولو ألِفه الناس."}},{"n":25,"reflection":{"text":"«وما أرسلنا من قبلك من رسول إلا نوحي إليه أنه لا إله إلا أنا فاعبدون»، وما أرسلنا قبلك من رسولٍ إلا أوحينا إليه أنه لا معبودَ بحقٍّ إلا أنا فاعبدوني وحدي؛ ففي هذا أنّ التوحيدَ هو زبدةُ رسالةِ كلِّ نبيّ، وأنّ الدينَ في أصله واحد؛ فاعلم أنّ غايةَ الرسالاتِ كلِّها إفرادُ الله بالعبادة، فحقّق التوحيدَ فهو دينُ الأنبياءِ أجمعين.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["لا إله إلا أنا فاعبدون"],"heart_state":{"text":"تحقيقُ التوحيدِ الذي هو زبدةُ رسالةِ كلِّ نبيّ."},"action":{"text":"حقّق التوحيدَ وأخلص العبادةَ لله وحده، فهو خلاصةُ دعوةِ الرسلِ جميعًا من أوّلهم إلى آخرهم؛ فما بُعِث نبيٌّ إلا بـ«لا إله إلا الله»، فاجعلها أصلَ دينك وعملك."}},{"n":26,"reflection":{"text":"«وقالوا اتخذ الرحمن ولدا سبحانه بل عباد مكرمون»، وقال المشركون: اتّخذ الرحمنُ الملائكةَ بناتٍ (ولدًا)، تنزّه الله عن ذلك، بل الملائكةُ عبادٌ مكرَمون عند الله لا أولاد؛ ففي هذا تنزيهُ الله عن الولد، وبيانُ أنّ الملائكةَ عبيدٌ مكرَمون؛ فنزّه الله عن الولدِ والشريك، وأنزل الملائكةَ منزلتهم عبيدًا مكرَمين لا آلهةً ولا أبناء.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"تنزيهُ الله عن الولد، وإنزالُ الخلقِ منازلهم."},"action":{"text":"نزّه الله عن الولدِ والشريك، ولا ترفع مخلوقًا فوق منزلته؛ فالملائكةُ ــ مع كرامتهم ــ عبادٌ لله لا أبناءٌ ولا آلهة؛ فأخلص العبادةَ لله، ولا تغلُ في تعظيمِ مخلوقٍ حتى تعبده."}},{"n":27,"reflection":{"text":"«لا يسبقونه بالقول وهم بأمره يعملون»: الملائكةُ لا يقولون قولًا إلا بعد إذنِ الله، ولا يعملون إلا بأمره، غايةُ الأدبِ والطاعة؛ ففي هذا كمالُ أدبِ الملائكةِ وطاعتهم لله، وأنّ العبدَ الكاملَ من لا يتقدّم بين يدي ربّه؛ فتأدّب مع الله فلا تتقدّم بين يديه بقولٍ أو فعلٍ لم يأذن به، والزم أمره في كلِّ شيء.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"التأدّبُ مع الله وعدمُ التقدّمِ بين يديه."},"action":{"text":"تأدّب مع الله فلا تقل ولا تفعل إلا بما أذن به شرعه، ولا تتقدّم بين يديه برأيك وهواك؛ فالملائكةُ لا يسبقونه بالقولِ ويعملون بأمره، فاقتدِ بهم في الأدبِ والانقيادِ لأمرِ الله."}},{"n":28,"reflection":{"text":"«يعلم ما بين أيديهم وما خلفهم ولا يشفعون إلا لمن ارتضى وهم من خشيته مشفقون»: يعلم الله أحوالَ الملائكةِ كلَّها، ولا يشفعون إلا لمن رضي الله عنه، وهم مع علوِّ منزلتهم من خشيةِ الله خائفون مشفقون؛ ففي هذا أنّ الشفاعةَ بإذنِ الله ورضاه، وأنّ الخشيةَ صفةُ المقرَّبين؛ فاجعل الخشيةَ في قلبك كخشيةِ الملائكة، فأعلمُ الخلقِ بالله أخشاهم له.","source":"تفسير السعدي","grade":"ma'thur"},"names":["من خشيته مشفقون"],"heart_state":{"text":"لزومُ خشيةِ الله، والعلمُ بأنّ الشفاعةَ بإذنه."},"action":{"text":"اجعل في قلبك خشيةً لله كخشيةِ الملائكةِ المقرَّبين، فمع علوِّ منزلتهم هم مشفقون من خشيته؛ فكلّما ازددت علمًا بالله ازددت له خشيةً؛ واعلم أنّ الشفاعةَ لا تكون إلا بإذنه ورضاه."}},{"n":29,"reflection":{"text":"«ومن يقل منهم إني إله من دونه فذلك نجزيه جهنم كذلك نجزي الظالمين»، ومن يدّعِ من الملائكةِ أو غيرهم أنه إلهٌ من دون الله ــ فرضًا ــ فجزاؤه جهنم، كذلك نجزي الظالمين بالشرك؛ ففي هذا أنّ دعوى الألوهيّةِ أعظمُ الظلمِ وجزاؤها النار، وأنّ حقَّ الألوهيّةِ لله وحده؛ فأخلص الألوهيّةَ لله، واعلم أنّ أعظمَ الظلمِ الشركُ وادّعاءُ ما هو حقُّ الله.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"إفرادُ الله بالألوهيّة، والحذرُ من أعظمِ الظلم."},"action":{"text":"أفرِد الله بالألوهيّةِ والعبادة، واعلم أنّ الشركَ ودعوى ما هو حقُّ الله أعظمُ الظلمِ وجزاؤه جهنم؛ فاحذر كلَّ ما يخدش التوحيد، وأعطِ الربوبيّةَ والألوهيّةَ لمستحقّها وحده سبحانه."}}]},{"title":"آياتُ الله في الكونِ الدالّةُ عليه","range":[30,33],"theme":"فتقُ السماواتِ والأرض، والماءُ أصلُ الحياة، والجبالُ والفلك","verses":[{"n":30,"reflection":{"text":"«أولم ير الذين كفروا أن السماوات والأرض كانتا رتقا ففتقناهما وجعلنا من الماء كل شيء حي أفلا يؤمنون»: أولم يعلم الكفارُ أنّ السماواتِ والأرضَ كانتا ملتصقتين ففصلناهما، وجعلنا من الماءِ كلَّ شيءٍ حيّ، أفلا يؤمنون بمن فعل ذلك؟ ففي هذا آيتان عظيمتان: فتقُ السماواتِ والأرض، وجعلُ الماءِ أصلَ الحياة، وكلاهما يدلّ على القدرةِ والوحدانيّة؛ فتأمّل هذه الآياتِ لتزداد إيمانًا، واعلم أنّ من قدر على ذلك قادرٌ على البعث.","source":"تفسير السعدي","grade":"ma'thur"},"names":["جعلنا من الماء كل شيء حي"],"heart_state":{"text":"التأمّلُ في آياتِ الخلقِ لزيادةِ الإيمان."},"action":{"text":"تأمّل في عظيمِ خلقِ الله: فتقِ السماواتِ والأرض، وجعلِ الماءِ أصلًا لكلِّ حيّ؛ فذلك يدلّ على قدرتِه ووحدانيّتِه ويزيدك إيمانًا؛ ومن قدر على هذا البدءِ قادرٌ على البعثِ، فآمن واعمل."}},{"n":31,"reflection":{"text":"«وجعلنا في الأرض رواسي أن تميد بهم وجعلنا فيها فجاجا سبلا لعلهم يهتدون»، وجعلنا في الأرضِ جبالًا ثوابتَ لئلا تضطرب بأهلها، وجعلنا فيها طرقًا واسعةً بين الجبالِ ليهتدوا في أسفارهم؛ ففي هذا نعمةُ تثبيتِ الأرضِ وتيسيرِ السبل، وأنّ في ذلك آياتٍ ونعمًا؛ فاشكر الله على ثباتِ أرضك وتيسيرِ سبلك، وتأمّل نعمه في تدبيرِ ما تعيش عليه.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"شكرُ نعمةِ تثبيتِ الأرضِ وتيسيرِ السبل."},"action":{"text":"اشكر الله على أن ثبّت الأرضَ بالجبالِ فلا تميد بك، ويسّر فيها السبلَ لتهتدي في أسفارك ومعاشك؛ وتأمّل هذه النعمَ التي تغفل عنها، فكلُّها آياتٌ تدلّ على المُنعِمِ وتدعو لشكره."}},{"n":32,"reflection":{"text":"«وجعلنا السماء سقفا محفوظا وهم عن آياتها معرضون»، وجعلنا السماءَ سقفًا مرفوعًا محفوظًا من السقوطِ ومن استراقِ الشياطين، وهم عن آياتها (شمسِها وقمرِها ونجومِها) معرضون لا يتفكّرون؛ ففي هذا نعمةُ حفظِ السماءِ فوقنا، وذمُّ الإعراضِ عن التفكّرِ في آياتها؛ فتفكّر في آياتِ السماءِ فوقك، ولا تكن من المعرضين الغافلين عن عجائبِ خلقِ الله.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"التفكّرُ في آياتِ السماء، ونبذُ الإعراضِ عنها."},"action":{"text":"ارفع بصرك وقلبك إلى آياتِ السماءِ المحفوظةِ فوقك فتفكّر فيها، ولا تكن من المعرضين الغافلين عنها؛ فكم في السماءِ من آيةٍ تدلّ على عظمةِ خالقها، تزيد المتفكّرَ إيمانًا وخشية."}},{"n":33,"reflection":{"text":"«وهو الذي خلق الليل والنهار والشمس والقمر كل في فلك يسبحون»، وهو الذي خلق الليلَ والنهارَ والشمسَ والقمر، كلٌّ منها يجري في مدارِه لا يحيد عنه؛ ففي هذا آيةُ انتظامِ الأفلاكِ بتقديرِ الله، وأنّ هذا النظامَ البديعَ يدلّ على مدبّرٍ حكيم؛ فتأمّل دقّةَ نظامِ الليلِ والنهارِ والشمسِ والقمر، فذلك دليلٌ على عظمةِ الله وحكمته، يدعوك لعبادته وشكره.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["كل في فلك يسبحون"],"heart_state":{"text":"التأمّلُ في انتظامِ الأفلاكِ دليلًا على حكمةِ الله."},"action":{"text":"تأمّل دقّةَ نظامِ الليلِ والنهارِ وجريانِ الشمسِ والقمرِ في مداريهما بلا اختلال، فذلك دليلُ عظمةِ الله وحكمته وقدرته؛ فمن تأمّل هذا النظامَ البديعَ خضع لمدبّرِه وعبده وشكره."}}]},{"title":"حتميةُ الموتِ وابتلاءُ النفوس","range":[34,37],"theme":"أنّ كلَّ نفسٍ ذائقةُ الموت، والابتلاءُ بالخيرِ والشرّ، وعجلةُ الإنسان","verses":[{"n":34,"reflection":{"text":"«وما جعلنا لبشر من قبلك الخلد أفإن مت فهم الخالدون»، وما جعلنا لأحدٍ من البشرِ قبلك يا محمد البقاءَ في الدنيا، أفإن متَّ أنت فهم يبقون خالدين؟ لا، بل الكلُّ يموت؛ ففي هذا أنّ الموتَ حقٌّ على الجميع لا يفلت منه أحد، وأنّ الخلودَ في الدنيا محال؛ فاستعدَّ للموتِ الذي لا مفرَّ منه، ولا تعش كأنك مخلَّد، فكلُّ نفسٍ راحلة.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"استحضارُ حتميةِ الموتِ والاستعدادُ له."},"action":{"text":"استحضر أنّ الموتَ حقٌّ عليك كما هو على كلِّ من قبلك، فلا خلودَ في الدنيا لأحد؛ فاستعدَّ له بالعملِ الصالحِ والتوبة، ولا تعش كأنك باقٍ، فكلُّ حيٍّ إلى رحيل."}},{"n":35,"reflection":{"text":"«كل نفس ذائقة الموت ونبلوكم بالشر والخير فتنة وإلينا ترجعون»: كلُّ نفسٍ ستذوق الموتَ لا محالة، ونختبركم بالمصائبِ والنعمِ لننظر شكركم وصبركم، وإلينا مرجعكم للحساب؛ ففي هذا أنّ الدنيا دارُ ابتلاءٍ بالخيرِ والشرّ، وأنّ الغايةَ الرجوعُ إلى الله؛ فاعلم أنّ ما يصيبك من سرّاءَ وضرّاءَ ابتلاء، فاشكر في النعمةِ واصبر في المصيبة، واستعدَّ للرجوعِ إلى الله.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["كل نفس ذائقة الموت"],"heart_state":{"text":"الصبرُ في الضرّاءِ والشكرُ في السرّاءِ لأنهما ابتلاء."},"action":{"text":"اعلم أنّ ما يصيبك من خيرٍ وشرٍّ فتنةٌ يختبر الله بها شكرك وصبرك، فاشكر عند النعمةِ واصبر عند المصيبة؛ فكلاهما امتحان، وإليه ترجع فتُجزى بما كان منك، فأحسن في الحالين."}},{"n":36,"reflection":{"text":"«وإذا رآك الذين كفروا إن يتخذونك إلا هزوا أهذا الذي يذكر آلهتكم وهم بذكر الرحمن هم كافرون»، وإذا رآك الكفارُ ما يتّخذونك إلا موضعَ استهزاء، يقولون: أهذا الذي يعيب آلهتكم؟ وهم مع استهزائهم بك كافرون بذكرِ الرحمنِ نفسِه؛ ففي هذا صبرُ النبيِّ ﷺ على استهزاءِ الكفار، وأنّ المستهزئَ بأهلِ الحقِّ كافرٌ بالحقّ؛ فاصبر على استهزاءِ السفهاءِ بك لأجلِ الحقّ، ولا يصدّنك ذلك عن دينك، فاستهزاؤهم علامةُ إعراضهم.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الصبرُ على الاستهزاءِ لأجلِ الحقّ."},"action":{"text":"اصبر على استهزاءِ الجاهلين بك حين تلزم الحقَّ وتدعو إليه، ولا يصدّنك سخرهم عن دينك؛ فاستهزاؤهم دليلُ إعراضهم لا نقصٍ فيك، والعاقبةُ لأهلِ الحقِّ لا للمستهزئين."}},{"n":37,"reflection":{"text":"«خلق الإنسان من عجل سأريكم آياتي فلا تستعجلون»: طُبِع الإنسانُ على العجلةِ واستعجالِ الأمور، سأريكم آياتي ووعيدي فلا تستعجلوا وقوعه؛ ففي هذا أنّ العجلةَ من طبعِ الإنسان، وأنّ استعجالَ العذابِ حمق؛ فجاهد طبعَ العجلةِ في نفسك، وتأنَّ في أمورك، ولا تستعجل ما وعد الله به فهو آتٍ في وقته.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["خلق الإنسان من عجل"],"heart_state":{"text":"مجاهدةُ طبعِ العجلةِ ولزومُ التأنّي."},"action":{"text":"جاهد طبعَ العجلةِ في نفسك وتأنَّ في أقوالك وأفعالك وأحكامك، فالعجلةُ تورث الزلل؛ ولا تستعجل ما وعد الله به من نصرٍ أو جزاء، فكلُّ آتٍ في وقتِه المقدَّرِ بحكمة."}}]},{"title":"استعجالُهم العذابَ وغفلتُهم عن حفظِ الله","range":[38,44],"theme":"استهزاؤهم بالوعد، وأنّ العذابَ يأتي بغتة، وأنّ الرحمنَ يكلؤهم","verses":[{"n":38,"reflection":{"text":"«ويقولون متى هذا الوعد إن كنتم صادقين»، ويقول المكذّبون استعجالًا واستهزاءً: متى يقع هذا الوعدُ بالعذابِ أو القيامةِ إن كنتم صادقين؟ ففي هذا استعجالُهم للعذابِ استبعادًا له، وأنّ الجاهلَ يستعجل ما يجهل خطره؛ فلا تستعجل أمرَ الله ولا تستبعده، فما وعد به واقعٌ في وقته، والاستعجالُ لا يقرّبه ولا يبعده.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"تركُ استعجالِ أمرِ الله واستبعادِه."},"action":{"text":"لا تستعجل وعدَ الله ولا وعيدَه ولا تستبعده، فكلُّ ما أخبر به واقعٌ في وقته المقدَّر؛ والاستعجالُ من الجهلِ بحكمةِ التأجيل، فالزم اليقينَ والاستعدادَ بدل الاستعجالِ والاستبعاد."}},{"n":39,"reflection":{"text":"«لو يعلم الذين كفروا حين لا يكفون عن وجوههم النار ولا عن ظهورهم ولا هم ينصرون»: لو يعلم الكفارُ الوقتَ الذي لا يدفعون فيه النارَ عن وجوههم ولا ظهورهم ولا ينصرهم أحد، لما استعجلوا العذاب؛ ففي هذا تصويرُ هولِ إحاطةِ النارِ بهم من كلِّ جهةٍ بلا ناصر، وأنّ الجاهلَ يستهزئ بما لو علمه لفزع؛ فاستحضر هولَ النارِ لتحذرها، فمن علم شدّتها لم يستعجلها ولم يعمل بما يوردها.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"استحضارُ هولِ النارِ لتُحذَر أسبابُها."},"action":{"text":"استحضر هولَ النارِ التي تحيط بأهلها من كلِّ جهةٍ بلا ناصر، لتحذر ما يوردها من الكفرِ والمعاصي؛ فمن علم شدّةَ عذابها جدَّ في اجتنابِ أسبابه، ولم يستهزئ بالوعيدِ ولا استعجله."}},{"n":40,"reflection":{"text":"«بل تأتيهم بغتة فتبهتهم فلا يستطيعون ردها ولا هم ينظرون»: بل تأتيهم الساعةُ أو العذابُ فجأةً فتحيّرهم وتدهشهم، فلا يقدرون على ردّها ولا يُمهَلون؛ ففي هذا أنّ العذابَ يأتي بغتةً فيقطع كلَّ حيلة، وأنّ الغفلةَ عنه لا تدفعه؛ فلا تركن إلى تأخّرِ العذابِ فقد يأتي بغتة، واستعدَّ دائمًا كأنّ الموعدَ الآن، فالبغتةُ تفجأ الغافلين.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاستعدادُ الدائمُ خشيةَ إتيانِ الأمرِ بغتة."},"action":{"text":"استعدَّ دائمًا للموتِ والحسابِ كأنه واقعٌ الآن، فإنّ العذابَ والساعةَ يأتيان بغتةً فيبهتان الغافلين بلا مهلةٍ للتدارك؛ فلا تسوّف التوبةَ والعملَ اتّكالًا على التأخّر، فالبغتةُ لا تنتظر."}},{"n":41,"reflection":{"text":"«ولقد استهزئ برسل من قبلك فحاق بالذين سخروا منهم ما كانوا به يستهزئون»، ولقد استُهزئ برسلٍ قبلك يا محمد، فنزل بالمستهزئين العذابُ الذي كانوا يستعجلونه ويستهزئون به؛ ففي هذا تسليةٌ للنبيِّ ﷺ، وأنّ عاقبةَ الاستهزاءِ بالحقِّ وخيمة؛ فتسلَّ بأنّ الرسلَ قبلك لاقوا الاستهزاء، واحذر الاستهزاءَ بالحقِّ فإنه يحيق بصاحبه.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"التسلّي بسنّةِ الاستهزاءِ بالرسل، والحذرُ منه."},"action":{"text":"تسلَّ عند استهزاءِ الناسِ بك على الحقِّ بأنّ الرسلَ قبلك لاقوا مثله، فالعاقبةُ لهم؛ واحذر أنت أن تستهزئ بشيءٍ من الحقِّ أو أهله، فإنّ عاقبةَ الاستهزاءِ تحيق بصاحبها."}},{"n":42,"reflection":{"text":"«قل من يكلؤكم بالليل والنهار من الرحمن بل هم عن ذكر ربهم معرضون»: قل: من يحفظكم ويحرسكم بالليلِ والنهارِ من بأسِ الرحمنِ إن أراده بكم؟ لا أحد، بل هم عن ذكرِ ربّهم وشكرِ حفظه معرضون؛ ففي هذا أنّ الله وحده الحافظُ الكالئُ لعباده، وأنّ الغفلةَ عن شكرِ حفظه ظلم؛ فاعلم أنّ الله يكلؤك في ليلك ونهارك، فاشكر حفظه بذكرِه وطاعته، ولا تُعرِض عنه.","source":"تفسير السعدي","grade":"ma'thur"},"names":["من يكلؤكم بالليل والنهار"],"heart_state":{"text":"استشعارُ حفظِ الله ومقابلتُه بالشكرِ والذكر."},"action":{"text":"استشعر أنّ الله يحفظك ويكلؤك في ليلك ونهارك من كلِّ سوء، فلولا حفظه لهلكت؛ فقابل ذلك بذكرِه وشكرِه وطاعته، ولا تكن من المعرضين الغافلين عن فضلِ من يحرسهم وهم عنه غافلون."}},{"n":43,"reflection":{"text":"«أم لهم آلهة تمنعهم من دوننا لا يستطيعون نصر أنفسهم ولا هم منا يصحبون»: أم لهؤلاء المشركين آلهةٌ تمنعهم من عذابنا؟ لا، فآلهتهم لا تقدر على نصرِ أنفسها فكيف تنصرهم، ولا هم يُجارون من عذابنا؟ ففي هذا عجزُ الآلهةِ الباطلةِ عن النصرِ والمنع، وأنّ العاجزَ لا يُعبَد؛ فلا تعتمد على من لا يملك نصرَ نفسه، وأخلص التوكّلَ على الله القادرِ وحده على النصرِ والحفظ.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"التوكّلُ على الله وحده لعجزِ ما سواه."},"action":{"text":"لا تعتمد في دفعِ الضرِّ أو جلبِ النفعِ على من لا يملك نصرَ نفسه، فما دون الله عاجز؛ وأخلص توكّلك على الله القادرِ على كلِّ شيء؛ فمن اعتمد على عاجزٍ خُذِل، ومن توكّل على الله كُفِي."}},{"n":44,"reflection":{"text":"«بل متعنا هؤلاء وآباءهم حتى طال عليهم العمر أفلا يرون أنا نأتي الأرض ننقصها من أطرافها أفهم الغالبون»: بل متّعنا هؤلاء وآباءهم بطولِ العمرِ والنعمِ استدراجًا، أفلا يرون أنا ننقص الأرضَ من أطرافها (بموتِ أهلها أو فتحِ المسلمين لها)؟ أفهم الغالبون؟ لا؛ ففي هذا أنّ طولَ المتاعِ استدراج، وأنّ تناقصَ ديارِ الكفرِ علامةُ زوالِ أمرهم؛ فلا يغرّنك طولُ متاعِ المبطلين، فإنّ أمرهم إلى نقصٍ وزوال، والغلبةُ للحقّ.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"عدمُ الاغترارِ بطولِ متاعِ المبطلين وزوالِ أمرهم."},"action":{"text":"لا يغرّنك ما للمبطلين من طولِ عمرٍ وسعةِ متاع، فإنما هو استدراج، وأمرهم إلى نقصٍ وزوال؛ فالعاقبةُ والغلبةُ لأهلِ الحقّ، فاثبت على الحقِّ ولا تنخدع بمظاهرِ قوّةِ الباطل."}}]},{"title":"الإنذارُ بالوحي، وموازينُ القسط، ونعمةُ الذكر","range":[45,50],"theme":"أنّ الإنذارَ بالوحي، والميزانُ العدلُ يوم القيامة، والقرآنُ ذكرٌ مبارك","verses":[{"n":45,"reflection":{"text":"«قل إنما أنذركم بالوحي ولا يسمع الصم الدعاء إذا ما ينذرون»: قل: إنما أخوّفكم بما أوحاه الله إليّ لا بشيءٍ من عندي، ولكنّ الصمَّ (المعرضين) لا يسمعون الإنذارَ سماعَ انتفاع؛ ففي هذا أنّ الإنذارَ إنما يكون بالوحيِ لا بالرأي، وأنّ الإعراضَ يُصِمّ عن الحقّ؛ فتلقَّ الإنذارَ من الوحيِ بقلبٍ سميعٍ منتفع، ولا تكن كالأصمِّ المعرضِ الذي لا ينتفع بالتذكير.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"تلقّي الإنذارِ من الوحيِ بقلبٍ سميعٍ منتفع."},"action":{"text":"تلقَّ إنذارَ الوحيِ ووعيدَه بقلبٍ سميعٍ خاشعٍ منتفع، وأصغِ إليه إصغاءَ من يريد النجاة؛ ولا تكن كالأصمِّ المعرضِ الذي يسمع بأذنه ولا يعي بقلبه، فيُنذَر ولا ينتفع."}},{"n":46,"reflection":{"text":"«ولئن مستهم نفحة من عذاب ربك ليقولن يا ويلنا إنا كنا ظالمين»، ولئن أصاب هؤلاء المستعجلين المستهزئين شيءٌ يسيرٌ من عذابِ ربّك ليقولنّ: يا هلاكَنا إنا كنا ظالمين؛ ففي هذا أنّ المستهزئَ يعترف بظلمه عند أدنى عذاب، وأنّ قوّةَ الباطلِ تنهار عند البأس؛ فاعتبر بأنّ أهلَ الباطلِ ينكسرون عند أدنى بلاء، ولا تغترَّ بجلَدهم الظاهر، وبادر بالتوبةِ قبل مسِّ العذاب.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"عدمُ الاغترارِ بجلَدِ المبطلين، والمبادرةُ بالتوبة."},"action":{"text":"لا تغترَّ بما يظهره أهلُ الباطلِ من قوّةٍ وجلَد، فإنّ أدنى نفحةٍ من عذابِ الله تكشف ضعفهم فيعترفون بظلمهم؛ فبادر أنت بالتوبةِ والاعترافِ بالتقصيرِ قبل أن يمسّك العذابُ فلا ينفع."}},{"n":47,"reflection":{"text":"«ونضع الموازين القسط ليوم القيامة فلا تظلم نفس شيئا وإن كان مثقال حبة من خردل أتينا بها وكفى بنا حاسبين»، ونضع الموازينَ العادلةَ يوم القيامةِ فلا يُظلَم أحدٌ شيئًا، وإن كان العملُ بوزنِ حبّةِ خردلٍ صغيرةً أحضرناها ووزنّاها، وكفى بنا محاسبين مُحصين؛ ففي هذا كمالُ عدلِ الله في الجزاء، ودقّةُ الحساب، وأنّ أصغرَ عملٍ محسوب؛ فراقب صغيرَ عملك وكبيرَه، فكلُّه موزونٌ محاسَبٌ عليه، ولا تحتقر ذرّةً من خيرٍ أو شرّ.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["الموازين القسط","كفى بنا حاسبين"],"heart_state":{"text":"مراقبةُ صغيرِ العملِ لدقّةِ الميزانِ وعدلِ الحساب."},"action":{"text":"راقب دقيقَ عملك وجليلَه، فكلُّه يوزن يوم القيامةِ بميزانِ العدلِ ولو كان مثقالَ خردلة؛ فلا تحتقر صغيرةً من حسنةٍ فتتركها، ولا صغيرةً من سيّئةٍ فتفعلها، فالميزانُ لا يغادر شيئًا."}},{"n":48,"reflection":{"text":"«ولقد آتينا موسى وهارون الفرقان وضياء وذكرا للمتقين»، ولقد آتينا موسى وهارونَ التوراةَ التي تفرّق بين الحقِّ والباطل، ونورًا يُهتدى به، وعظةً وتذكرةً للمتّقين؛ ففي هذا شرفُ الكتبِ المُنزَّلةِ بأنها فرقانٌ وضياءٌ وذكر، وأنّ المنتفعَ بها المتّقون؛ فاجعل القرآنَ فرقانك بين الحقِّ والباطل، وضياءك في الظلمات، وذكرك، فبه تكون من المتّقين.","source":"تفسير السعدي","grade":"ma'thur"},"names":["الفرقان","ضياء وذكرا للمتقين"],"heart_state":{"text":"اتّخاذُ الكتابِ فرقانًا وضياءً وذكرًا."},"action":{"text":"اجعل القرآنَ فرقانك تفرّق به بين الحقِّ والباطلِ في كلِّ أمر، وضياءك تستنير به في ظلماتِ الحياة، وذكرك تتّعظ به؛ فبه ينتفع المتّقون، فكن منهم بتلاوتِه وتدبّرِه والعملِ به."}},{"n":49,"reflection":{"text":"«الذين يخشون ربهم بالغيب وهم من الساعة مشفقون»: المتّقون هم الذين يخافون ربّهم في السرِّ حيث لا يراهم إلا الله، وهم من أهوالِ القيامةِ خائفون حذرون؛ ففي هذا أنّ حقيقةَ التقوى خشيةُ الله في الغيب، والإشفاقُ من الساعة؛ فاخشَ الله في خلوتك كما تخشاه في علانيتك، وأشفِق من أهوالِ القيامة، فتلك صفةُ المتّقين المنتفعين بالوحي.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["يخشون ربهم بالغيب"],"heart_state":{"text":"خشيةُ الله في الغيب، والإشفاقُ من القيامة."},"action":{"text":"اخشَ الله في سرّك وخلوتك حيث لا يراك أحدٌ سواه كما تخشاه في العلن، وأشفِق من أهوالِ يومِ القيامةِ فاستعدَّ له؛ فخشيةُ الغيبِ حقيقةُ التقوى، وبها ينتفع العبدُ بالذكر."}},{"n":50,"reflection":{"text":"«وهذا ذكر مبارك أنزلناه أفأنتم له منكرون»، وهذا القرآنُ ذكرٌ كثيرُ الخيرِ والبركةِ أنزلناه إليكم، أفتنكرونه بعد ما فيه من الهدى والنور؟ ففي هذا وصفُ القرآنِ بالبركةِ وكثرةِ الخير، وإنكارُ جحدِه بعد وضوحِ فضله؛ فاعرف بركةَ القرآنِ وخيره، وأقبل عليه بالتصديقِ والعمل، ولا تكن من المنكرين لأعظمِ نعمةٍ أُنزِلت.","source":"تفسير السعدي","grade":"ma'thur"},"names":["ذكر مبارك"],"heart_state":{"text":"معرفةُ بركةِ القرآنِ والإقبالُ عليه بالتصديقِ والعمل."},"action":{"text":"اعرف بركةَ القرآنِ وكثرةَ خيره، وأقبل عليه تلاوةً وتدبّرًا وعملًا وتعظيمًا، ولا تُعرِض عنه ولا تنكر شيئًا منه؛ فهو ذكرٌ مبارَكٌ من أنزله، من تمسّك به بورك له في دينه ودنياه."}}]},{"title":"إبراهيمُ يحاجّ قومَه في الأصنام","range":[51,58],"theme":"رشدُ إبراهيم، وإنكارُه عبادةَ التماثيل، وعزمُه على كسرها","verses":[{"n":51,"reflection":{"text":"«ولقد آتينا إبراهيم رشده من قبل وكنا به عالمين»، ولقد آتينا إبراهيمَ هدايته وصلاحه من قبلِ موسى وهارون، وكنا عالمين بأنه أهلٌ لذلك؛ ففي هذا أنّ الرشدَ منحةٌ من الله يؤتيها من علم أهليّته، وأنّ الله يصطفي من يعلم صلاحه؛ فاطلب الرشدَ من الله، واعلم أنه يؤتيه من صدق في طلبه، فهو أعلمُ بمن يستحقّه.","source":"تفسير السعدي","grade":"ma'thur"},"names":["آتينا إبراهيم رشده"],"heart_state":{"text":"طلبُ الرشدِ من الله الذي يؤتيه أهلَه."},"action":{"text":"اطلب الرشدَ والهدايةَ من الله، واجتهد في أسبابهما بالصدقِ والإخلاص؛ فالله يؤتي رشده من علم أهليّته له، وهو أعلمُ بعباده؛ فصدقُك في الطلبِ سبيلٌ لنيلِ توفيقه."}},{"n":52,"reflection":{"text":"«إذ قال لأبيه وقومه ما هذه التماثيل التي أنتم لها عاكفون»: حين قال إبراهيمُ لأبيه وقومه منكرًا: ما هذه التماثيلُ (الأصنام) التي تقيمون على عبادتها؟ ففي هذا إنكارُ إبراهيمَ للشركِ بالسؤالِ التقريريِّ الموقظ، وأنّ الداعيَ يبدأ بلفتِ العقلِ إلى بطلانِ المعبود؛ فأنكر المنكرَ بأسلوبٍ يوقظ العقل، وابدأ بالأقربين، ولا تسكت عن باطلٍ يُعبَد من دون الله.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"إنكارُ الشركِ بأسلوبٍ يوقظ العقل."},"action":{"text":"أنكر الباطلَ والمنكرَ بأسلوبٍ يوقظ عقلَ المخاطبِ ويحمله على التفكّر، وابدأ بأقربِ الناسِ إليك؛ فإبراهيمُ سأل قومه سؤالَ منكِرٍ موقظٍ لا مقرِّرٍ، فاستعمل الحكمةَ في الإنكار."}},{"n":53,"reflection":{"text":"«قالوا وجدنا آباءنا لها عابدين»: قالوا: وجدنا آباءنا يعبدونها فاتّبعناهم؛ ففي هذا أنّ حجّةَ المبطلين تقليدُ الآباءِ بلا دليل، وأنّ التقليدَ الأعمى بابُ الضلال؛ فلا تتّبع أحدًا في باطلٍ لمجرّدِ أنه عادةُ الآباءِ والناس، بل زِن كلَّ أمرٍ بالحقّ، فالتقليدُ بلا دليلٍ ليس بحجّة.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"نبذُ التقليدِ الأعمى ووزنُ الأمورِ بالحقّ."},"action":{"text":"لا تتّبع عادةً أو معتقدًا لمجرّدِ أنه فعلُ الآباءِ أو الأكثرين، بل زِنه بميزانِ الحقِّ والدليل؛ فحجّةُ «وجدنا آباءنا» حجّةُ الضالّين، والمؤمنُ يتبع الدليلَ لا الأهواءَ والعادات."}},{"n":54,"reflection":{"text":"«قال لقد كنتم أنتم وآباؤكم في ضلال مبين»: قال إبراهيمُ صادعًا بالحقّ: لقد كنتم أنتم وآباؤكم في ضلالٍ واضحٍ بيّن؛ ففي هذا صراحةُ الداعيةِ في تسميةِ الباطلِ باطلًا ولو خالف تعظيمَ الآباء، وأنّ الحقَّ لا يُحابى فيه أحد؛ فقل الحقَّ صريحًا ولو خالف ما يعظّمه الناس، فتعظيمُ الآباءِ لا يبرّر اتّباعهم في الضلال.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الصراحةُ في الحقِّ وعدمُ المحاباةِ فيه."},"action":{"text":"قل الحقَّ صريحًا واضحًا ولو خالف ما يعظّمه الناسُ من عاداتِ الآباءِ والسادة، ولا تحابِ في الحقِّ أحدًا؛ فإبراهيمُ سمّى ضلالَ آبائهم ضلالًا مبينًا، فالحقُّ أحقُّ أن يُتَّبع من الرجال."}},{"n":55,"reflection":{"text":"«قالوا أجئتنا بالحق أم أنت من اللاعبين»: قالوا متعجّبين: أجئتنا بالحقِّ جادًّا أم أنت لاعبٌ مازح؟ ففي هذا استغرابُهم لمخالفةِ المألوف، وأنّ الحقَّ قد يُستغرَب لغرابته على المعتادين للباطل؛ فلا يهزّك استغرابُ الناسِ للحقّ، فكثيرًا ما يُستغرَب الحقُّ حين يألف الناسُ الباطل، والزم الجدَّ في الحقّ.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الثباتُ على الحقِّ ولو استغربه الناس."},"action":{"text":"لا يزعزعك استغرابُ الناسِ للحقِّ أو استبعادهم له، فكثيرًا ما يبدو الحقُّ غريبًا لمن ألِف الباطل؛ فالزم الجدَّ والثباتَ على الحقّ، وبيّنه بوضوح، فالغرابةُ في عينِ المعتادِ لا في الحقِّ نفسه."}},{"n":56,"reflection":{"text":"«قال بل ربكم رب السماوات والأرض الذي فطرهن وأنا على ذلكم من الشاهدين»: قال إبراهيمُ جادًّا: بل ربّكم الحقُّ هو ربُّ السماواتِ والأرضِ الذي خلقهنّ وأبدعهنّ، وأنا على ذلك من الشاهدين المؤمنين؛ ففي هذا تقريرُ الربوبيّةِ الحقّةِ بدليلِ الخلق، وشهادةُ إبراهيمَ للحقِّ وثباتُه عليه؛ فاشهد للحقِّ بلسانك وقلبك، واستدلَّ على ربّك بخلقِ السماواتِ والأرض، وأعلن إيمانك.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["رب السماوات والأرض الذي فطرهن"],"heart_state":{"text":"الشهادةُ للحقِّ والاستدلالُ على الله بخلقه."},"action":{"text":"اشهد للحقِّ بقلبك ولسانك وموقفك، واستدلَّ على ربوبيّةِ الله بخلقه للسماواتِ والأرض؛ فكن كإبراهيمَ شاهدًا للتوحيدِ معلنًا له، مستدلًّا عليه بآياتِ الله البيّنةِ في خلقه."}},{"n":57,"reflection":{"text":"«وتالله لأكيدن أصنامكم بعد أن تولوا مدبرين»، وأقسم إبراهيمُ في نفسه: والله لأحتالنّ على أصنامكم بكسرها بعد أن تنصرفوا عنها؛ ففي هذا عزمُ إبراهيمَ على تغييرِ المنكرِ بيده حين تمكّن، وأنّ الغيرةَ للتوحيدِ تحمل على الفعل؛ فليكن لك عزمٌ على تغييرِ المنكرِ بحسبِ استطاعتك وحكمتك، فالإيمانُ يبعث على العملِ لا القولِ وحده.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"العزمُ على تغييرِ المنكرِ بحسبِ الاستطاعةِ والحكمة."},"action":{"text":"لتكن لك غيرةٌ على التوحيدِ تبعثك على تغييرِ المنكرِ بيدك حيث تستطيع وبحكمة، فالإيمانُ عملٌ لا قولٌ فقط؛ فإبراهيمُ عزم على كسرِ الأصنامِ ليقيم الحجّة، فغيّر المنكرَ بقدرِ وسعك."}},{"n":58,"reflection":{"text":"«فجعلهم جذاذا إلا كبيرا لهم لعلهم إليه يرجعون»: فكسّر إبراهيمُ الأصنامَ وجعلها قطعًا محطّمةً إلا كبيرَها تركه، رجاءَ أن يرجعوا إليه فيسألوه فتقوم الحجّة؛ ففي هذا حكمةُ إبراهيمَ في ترتيبِ الحجّةِ العمليّة، وأنّ الداعيَ يستعمل الأسلوبَ الذي يُلزِم الخصمَ بالحقّ؛ فاستعمل الحكمةَ في إقامةِ الحجّة، ورتّب أسلوبك ليقود المخالفَ إلى الاعترافِ بالحقّ.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"استعمالُ الحكمةِ في إقامةِ الحجّةِ على المخالف."},"action":{"text":"استعمل الحكمةَ في إقامةِ الحجّةِ على المخالف، ورتّب أسلوبك بحيث يقوده إلى الاعترافِ بالحقِّ من نفسه؛ فإبراهيمُ أبقى كبيرَ الأصنامِ ليُلزِمهم الحجّةَ حين يسألونه، فالدعوةُ تحتاج حكمةً وتدبيرًا."}}]},{"title":"إقامةُ الحجّةِ ونجاةُ إبراهيمَ من النار","range":[59,70],"theme":"محاكمةُ إبراهيم، وإفحامُهم بحجّته، وجعلُ النارِ بردًا وسلامًا","verses":[{"n":59,"reflection":{"text":"«قالوا من فعل هذا بآلهتنا إنه لمن الظالمين»: قالوا لمّا رأوا أصنامهم محطّمة: من فعل هذا بآلهتنا؟ إنه لظالمٌ معتدٍ؛ ففي هذا أنهم سمّوا كاسرَ الأصنامِ ظالمًا وهم الظالمون بعبادتها، وأنّ المبطلَ يقلب الحقائق؛ فلا يهزّك أن يصفك المبطلون بالظلمِ وأنت على الحقّ، فالميزانُ الحقُّ لا وصفُ الناس.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الثباتُ وإن وصفك المبطلون بالظلمِ وأنت محقّ."},"action":{"text":"لا يزعزعك أن يصفك أهلُ الباطلِ بالظلمِ أو الإساءةِ وأنت على الحقّ، فهم يقلبون الحقائق؛ فزِن نفسك بميزانِ الحقِّ لا بأوصافهم، واثبت على ما تعلم أنه صواب، فوصفُهم لا يغيّر الحقيقة."}},{"n":60,"reflection":{"text":"«قالوا سمعنا فتى يذكرهم يقال له إبراهيم»: قالوا: سمعنا شابًّا يعيب الأصنامَ ويذكرها بسوءٍ اسمه إبراهيم؛ ففي هذا أنّ إبراهيمَ كان مشهورًا بإنكارِ الشركِ والصدعِ به، وأنّ الداعيَ يُعرَف بموقفه من الباطل؛ فليُعرَف عنك موقفك من الحقِّ وإنكارك للباطل، فالمؤمنُ يُعرَف بغيرته على دينه وصدعه بالحقّ.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"أن يُعرَف المؤمنُ بموقفه من الحقِّ وإنكارِ الباطل."},"action":{"text":"ليكن لك موقفٌ معلومٌ من الحقِّ ومن الباطلِ يُعرَف به عنك، فلا تكن إمّعةً بلا موقف؛ فإبراهيمُ عُرِف بإنكارِ الشرك، فاجعل غيرتك على دينك ظاهرةً في قولك وعملك بحكمةٍ وثبات."}},{"n":61,"reflection":{"text":"«قالوا فأتوا به على أعين الناس لعلهم يشهدون»: قالوا: أحضروا إبراهيمَ على مرأًى من الناسِ ليشهدوا محاكمته أو ليشهدوا عليه؛ ففي هذا أنّ الله هيّأ لإبراهيمَ منبرًا يعلن فيه الحقَّ أمام الجمع، وأنّ ما أراده الخصمُ لفضيحتِه صار منبرًا للحقّ؛ فثق بأنّ الله قد يجعل ما يكيده الخصومُ لك بابًا لإظهارِ الحقِّ على الملأ، فامضِ واثقًا.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الثقةُ بأنّ الله يجعل كيدَ الخصمِ منبرًا للحقّ."},"action":{"text":"ثق بأنّ الله قد يحوّل ما يكيده الخصومُ لفضيحتك إلى منبرٍ تُعلِن عليه الحقّ، فما جمعوا الناسَ لإبراهيمَ إلا فأقام فيهم الحجّة؛ فامضِ في الحقِّ واثقًا أنّ الله يدبّر لك ما يظهره."}},{"n":62,"reflection":{"text":"«قالوا أأنت فعلت هذا بآلهتنا يا إبراهيم»: قالوا: أأنت الذي كسّرت آلهتنا يا إبراهيم؟ ففي هذا مواجهتُهم لإبراهيمَ بالسؤال، وأنه ثبت لهم ولم يخف، تمهيدًا لإقامةِ الحجّة؛ فاثبت عند مواجهةِ الخصومِ ولا تجزع، فالثباتُ عند السؤالِ بابُ إقامةِ الحجّةِ وإظهارِ الحقّ.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الثباتُ عند مواجهةِ الخصومِ وعدمُ الجزع."},"action":{"text":"اثبت عند مواجهةِ الخصومِ ومساءلتهم لك على الحقِّ ولا تجزع ولا تتلعثم، فالثباتُ يمهّد لإقامةِ الحجّة؛ فإبراهيمُ ووجِه بالسؤالِ فثبت وأجاب بما أقام به الحجّةَ عليهم."}},{"n":63,"reflection":{"text":"«قال بل فعله كبيرهم هذا فاسألوهم إن كانوا ينطقون»: قال إبراهيمُ محتجًّا عليهم: بل فعله كبيرُهم هذا (تعريضًا ليُلزِمهم الحجّة)، فاسألوا الأصنامَ إن كانت تنطق؛ ففي هذا إقامةُ الحجّةِ بأسلوبٍ يكشف عجزَ آلهتهم، وأنّ المعرِّضَ لبيانِ الحقِّ غيرُ كاذب؛ فأقم الحجّةَ على المبطلِ بما يكشف بطلانه، واستعمل من الأساليبِ ما يُلزِمه الاعترافَ بعجزِ باطله.","source":"تفسير السعدي","grade":"ma'thur"},"names":["فاسألوهم إن كانوا ينطقون"],"heart_state":{"text":"إقامةُ الحجّةِ بما يكشف عجزَ الباطل."},"action":{"text":"أقم الحجّةَ على المخالفِ بأسلوبٍ يكشف عجزَ باطله ويُلزِمه الاعتراف، كما ألزم إبراهيمُ قومَه بأنّ آلهتهم لا تنطق؛ فبيّن الحقَّ بما يفضح الباطلَ من نفسه، فذلك أبلغُ في الإقناع."}},{"n":64,"reflection":{"text":"«فرجعوا إلى أنفسهم فقالوا إنكم أنتم الظالمون»: فرجع القومُ إلى عقولهم وتفكّروا، فقالوا: إنكم أنتم الظالمون بعبادةِ ما لا ينطق؛ ففي هذا أنّ الحجّةَ البالغةَ تردّ الإنسانَ إلى عقله فيبصر الحقّ، وأنّ التفكّرَ يكشف الضلال؛ فارجع إلى عقلك وفكّر في معتقداتك، فبالتفكّرِ ينكشف الباطل، والحجّةُ الصادقةُ تُرجِع الناسَ إلى الحقّ.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الرجوعُ إلى العقلِ والتفكّرِ لكشفِ الباطل."},"action":{"text":"ارجع إلى عقلك وحاسب معتقداتك وأعمالك بميزانِ الحقّ، فبالتفكّرِ الصادقِ ينكشف الباطلُ ويتبيّن الحقّ؛ فالحجّةُ البالغةُ ترجع المنصفَ إلى صوابه، فلا تغلق عقلك عن مراجعةِ نفسك."}},{"n":65,"reflection":{"text":"«ثم نكسوا على رءوسهم لقد علمت ما هؤلاء ينطقون»: ثم انتكسوا فعادوا إلى عنادهم بعد أن أبصروا الحقّ، وقالوا لإبراهيم: لقد علمت أنّ هذه الأصنامَ لا تنطق (فكيف نسألها؟)؛ ففي هذا أنّ العنادَ يردّ صاحبه إلى الباطلِ بعد وضوحِ الحقّ، وأنّ إقرارهم بعجزِ الأصنامِ حجّةٌ عليهم؛ فاحذر أن يردّك العنادُ إلى الباطلِ بعد ما تبيّن لك الحقّ، بل اتبع الحقَّ حين ينكشف.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من أن يردَّ العنادُ إلى الباطلِ بعد وضوحِ الحقّ."},"action":{"text":"احذر أن يغلبك العنادُ والكِبرُ فيردّك إلى الباطلِ بعد ما تبيّن لك الحقُّ كما انتكس القوم؛ بل اتبع الحقَّ فورَ انكشافه، ولا تكابر بعد قيامِ الحجّةِ عليك، فالمكابرةُ بعد البيانِ هلاك."}},{"n":66,"reflection":{"text":"«قال أفتعبدون من دون الله ما لا ينفعكم شيئا ولا يضركم»: قال إبراهيمُ موبّخًا: أفتعبدون من دون الله ما لا يقدر على نفعكم ولا ضرّكم؟ ففي هذا الحجّةُ العقليّةُ على بطلانِ عبادةِ العاجزِ عن النفعِ والضرّ، وأنّ المعبودَ الحقَّ من ينفع ويضرّ؛ فلا تعبد ولا ترجُ ولا تخف إلا من يملك النفعَ والضرّ، وهو الله وحده.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"إفرادُ الله بالعبادةِ لأنه وحده النافعُ الضارّ."},"action":{"text":"لا تصرف شيئًا من العبادةِ أو الرجاءِ أو الخوفِ إلا لله الذي يملك النفعَ والضرّ؛ فكلُّ ما سواه عاجزٌ لا ينفع ولا يضرّ، فكيف يُعبَد؟ فأخلص قلبك لله وحده، فهو النافعُ الضارُّ لا سواه."}},{"n":67,"reflection":{"text":"«أف لكم ولما تعبدون من دون الله أفلا تعقلون»: تبًّا لكم ولآلهتكم التي تعبدونها من دون الله، أفلا تستعملون عقولكم فتبصروا بطلان ذلك؟ ففي هذا إنكارُ إبراهيمَ الشديدُ للشرك، ودعوةٌ إلى إعمالِ العقل، وأنّ الشركَ مناقضٌ للعقل؛ فأعمل عقلك في أمرِ معبودك، فالشركُ سفهٌ يأباه العقلُ السليم، والتوحيدُ مقتضى العقلِ والفطرة.","source":"تفسير السعدي","grade":"ma'thur"},"names":["أفلا تعقلون"],"heart_state":{"text":"إعمالُ العقلِ في التوحيدِ ونبذُ الشرك."},"action":{"text":"أعمل عقلك في أمرِ عبادتك، فالشركُ سفهٌ يناقض العقلَ السليم، والتوحيدُ مقتضى العقلِ والفطرة؛ فلا تعبد إلا من يستحقُّ العبادةَ بكماله وقدرته، وابرأ من كلِّ معبودٍ باطلٍ لا يعقل."}},{"n":68,"reflection":{"text":"«قالوا حرقوه وانصروا آلهتكم إن كنتم فاعلين»: قالوا لمّا عجزوا عن الحجّة: أحرقوا إبراهيمَ وانصروا آلهتكم إن كنتم ناصرين لها؛ ففي هذا أنّ المبطلَ إذا عجز عن الحجّةِ لجأ إلى البطشِ والعنف، وأنّ ذلك دليلُ إفلاسه؛ فاعلم أنّ لجوءَ الخصمِ إلى العنفِ دليلُ انقطاعِ حجّته، فلا يزلزلك بطشُهم، فالحقُّ أقوى من نارهم.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"العلمُ بأنّ لجوءَ المبطلِ للعنفِ دليلُ عجزِ حجّته."},"action":{"text":"اعلم أنّ لجوءَ المخالفِ إلى العنفِ والبطشِ بعد عجزه عن الحجّةِ دليلُ إفلاسه لا قوّته؛ فلا يزعزعك تهديدُهم وأذاهم، واثبت على الحقّ، فمن انقطعت حجّته لجأ إلى القوّة، والعاقبةُ للحقّ."}},{"n":69,"reflection":{"text":"«قلنا يا نار كوني بردا وسلاما على إبراهيم»: قلنا للنارِ التي ألقوه فيها: كوني بردًا وسلامًا على إبراهيمَ، فلم تحرقه ولم تؤذه؛ ففي هذا نصرُ الله لوليّه بأعجبِ الأسباب، وأنّ النارَ لا تحرق إلا بإذنِ الله؛ فثق بأنّ الله ينصر أولياءه ولو بخرقِ العادات، فمن توكّل عليه كفاه، والأسبابُ كلُّها طوعُ أمره.","source":"تفسير السعدي","grade":"ma'thur"},"names":["يا نار كوني بردا وسلاما على إبراهيم"],"heart_state":{"text":"الثقةُ بنصرِ الله لأوليائه ولو بخرقِ العادات."},"action":{"text":"ثق بأنّ الله ينصر أولياءه الصادقين ولو بأعجبِ الأسبابِ وأخرقِها للعادة، فالنارُ لا تحرق إلا بإذنه؛ فمن توكّل على الله وصدق معه كفاه وحفظه، فاعتصم به وأخلص له، ولا تخف مع معيّته."}},{"n":70,"reflection":{"text":"«وأرادوا به كيدا فجعلناهم الأخسرين»، وأراد قومُ إبراهيمَ به كيدًا وإهلاكًا، فجعلناهم الأخسرين الأذلّين بردِّ كيدهم في نحورهم؛ ففي هذا أنّ كيدَ المبطلين بأهلِ الحقِّ يرتدّ عليهم، وأنّ العاقبةَ لأهلِ الحقّ؛ فلا تخف كيدَ الكائدين إذا كنت على الحقّ، فإنّ الله يردّ كيدهم ويجعلهم الأخسرين، والنصرُ لأوليائه.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"عدمُ الخوفِ من كيدِ المبطلين لأنه يرتدّ عليهم."},"action":{"text":"لا تخف كيدَ الكائدين ومكرَ الماكرين إذا كنت على الحقّ، فإنّ الله يردّ كيدهم في نحورهم ويجعلهم الأخسرين؛ فامضِ في حقّك متوكّلًا على الله، فكيدُ من عادى أولياءه راجعٌ عليهم."}}]},{"title":"نجاةُ إبراهيمَ ولوطٍ، وذريّةُ الأنبياء","range":[71,73],"theme":"نجاتُهما إلى الأرضِ المباركة، وهبةُ إسحاقَ ويعقوب، وجعلُهم أئمّة","verses":[{"n":71,"reflection":{"text":"«ونجيناه ولوطا إلى الأرض التي باركنا فيها للعالمين»، ونجّينا إبراهيمَ ولوطًا من قومهما إلى أرضِ الشامِ التي باركنا فيها للعالمين (بكثرةِ الأنبياءِ والخيراتِ فيها)؛ ففي هذا أنّ الله ينجّي أولياءه ويهيّئ لهم دارَ خيرٍ وبركة، وأنّ الهجرةَ في الله تعقبها البركة؛ فمن هاجر وفارق قومه لله أنجاه الله وباركه، فاثبت على الحقِّ ولو فارقت الأوطان.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الثقةُ بأنّ الله ينجّي المهاجرَ إليه ويباركه."},"action":{"text":"اثبت على الحقِّ ولو اضطرّك إلى مفارقةِ قومك أو وطنك، فإنّ الله ينجّي من هاجر إليه ويهيّئ له دارَ خيرٍ وبركة؛ فمن ترك شيئًا لله عوّضه خيرًا منه، كما نجّى إبراهيمَ ولوطًا وباركهما."}},{"n":72,"reflection":{"text":"«ووهبنا له إسحاق ويعقوب نافلة وكلا جعلنا صالحين»، ووهبنا لإبراهيمَ إسحاقَ ابنًا ويعقوبَ حفيدًا زيادةً وعطاءً، وجعلنا كلًّا منهم صالحًا؛ ففي هذا أنّ الله يعوّض المهاجرَ في سبيله بالذريّةِ الصالحة، وأنّ صلاحَ الذريّةِ نعمةٌ يهبها الله؛ فاطلب من الله الذريّةَ الصالحة، فهي خيرُ ما يوهب، وثمرةُ الصلاحِ والهجرةِ في الله.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"طلبُ الذريّةِ الصالحةِ من الله ورجاءُ عطائه."},"action":{"text":"اطلب من الله ذريّةً صالحةً، فهي من أعظمِ العطاءِ الذي يهبه لأوليائه؛ واعمل على صلاحِ نفسك، فإنّ الله يبارك في ذريّةِ الصالحين ويعوّض من ترك لأجله بالذريّةِ الطيّبةِ كإسحاقَ ويعقوب."}},{"n":73,"reflection":{"text":"«وجعلناهم أئمة يهدون بأمرنا وأوحينا إليهم فعل الخيرات وإقام الصلاة وإيتاء الزكاة وكانوا لنا عابدين»، وجعلناهم أئمّةً يقتدى بهم يهدون الناسَ بأمرنا، وأوحينا إليهم أن يفعلوا الخيراتِ ويقيموا الصلاةَ ويؤتوا الزكاة، وكانوا لنا عابدين مخلصين؛ ففي هذا أنّ الإمامةَ في الدينِ تُنال بالصبرِ واليقينِ والعمل، وأنّ أوصافَ القدوةِ العبادةُ والدعوةُ وفعلُ الخير؛ فاطلب أن تكون إمامًا في الخيرِ بالعملِ والدعوة، والزم فعلَ الخيراتِ والصلاةَ والزكاةَ والعبادة.","source":"تفسير السعدي","grade":"ma'thur"},"names":["أئمة يهدون بأمرنا"],"heart_state":{"text":"طلبُ الإمامةِ في الخيرِ بالعملِ والدعوةِ والعبادة."},"action":{"text":"اطلب أن تكون قدوةً وإمامًا في الخير يُهتدى بك، ولا تُنال هذه المنزلةُ إلا بلزومِ فعلِ الخيراتِ وإقامِ الصلاةِ وإيتاءِ الزكاةِ ودوامِ العبادة؛ فاجمع بين العملِ الصالحِ والدعوةِ إليه تكن من أئمّةِ الهدى."}}]},{"title":"لوطٌ ونوحٌ: النجاةُ والنصر","range":[74,77],"theme":"إيتاءُ لوطٍ الحكمَ ونجاتُه، واستجابةُ الله لنوحٍ ونصرُه","verses":[{"n":74,"reflection":{"text":"«ولوطا آتيناه حكما وعلما ونجيناه من القرية التي كانت تعمل الخبائث إنهم كانوا قوم سوء فاسقين»، ولوطًا آتيناه الحكمةَ والعلمَ والنبوّة، ونجّيناه من قريةٍ كانت تعمل الفواحشَ والخبائث، إنهم كانوا قومَ سوءٍ خارجين عن طاعةِ الله؛ ففي هذا أنّ الله ينجّي أولياءه من بين أهلِ الفسوق، وأنّ الفواحشَ سببُ الهلاك؛ فاعتزل أهلَ الخبائثِ والفسوق، واثبت على الطاعةِ بينهم، فالله ينجّي الصالحين من عذابِ الفاسقين.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"اعتزالُ أهلِ الفسوقِ والثباتُ على الطاعةِ بينهم."},"action":{"text":"اعتزل أهلَ الفواحشِ والفسوقِ في أفعالهم، واثبت على طاعةِ الله بينهم ولا تشاركهم؛ فالله ينجّي الصالحين من عذابِ المسيئين؛ فكن كلوطٍ صالحًا في قومٍ سوءٍ حتى ينجّيك الله."}},{"n":75,"reflection":{"text":"«وأدخلناه في رحمتنا إنه من الصالحين»، وأدخلنا لوطًا في رحمتنا (النجاةِ والجنّةِ) لأنه من الصالحين؛ ففي هذا أنّ الصلاحَ سببُ دخولِ رحمةِ الله، وأنّ العملَ الصالحَ طريقُ النجاة؛ فاعمل بالصلاحِ لتدخل في رحمةِ الله، فرحمتُه قريبٌ من المحسنين، والصالحون هم أهلها.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"العملُ بالصلاحِ لدخولِ رحمةِ الله."},"action":{"text":"اجتهد أن تكون من الصالحين قولًا وعملًا واعتقادًا، فبالصلاحِ تُدخَل في رحمةِ الله؛ فرحمتُه قريبٌ من المحسنين، والصالحون أهلُها، فاجعل الصلاحَ ديدنك في السرِّ والعلن."}},{"n":76,"reflection":{"text":"«ونوحا إذ نادى من قبل فاستجبنا له فنجيناه وأهله من الكرب العظيم»، واذكر نوحًا إذ دعا ربَّه من قبلِ هؤلاء الأنبياء، فاستجبنا له فنجّيناه وأهله المؤمنين من الكربِ العظيمِ (الطوفانِ أو أذى قومه)؛ ففي هذا أنّ الدعاءَ سببُ تفريجِ الكرب، وأنّ الله يستجيب لمن ناداه؛ فالجأ إلى الله بالدعاءِ عند الكرب، فهو يستجيب وينجّي، كما استجاب لنوحٍ ونجّاه من كربه العظيم.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"اللجوءُ إلى الله بالدعاءِ عند الكربِ ثقةً بالإجابة."},"action":{"text":"الجأ إلى الله بالدعاءِ والنداءِ عند كلِّ كربٍ يشتدّ عليك، واثقًا بأنه يستجيب وينجّي؛ فقد نادى نوحٌ فاستجاب الله له ونجّاه من الكربِ العظيم، فما خاب من دعا الله ولا ذلَّ من لجأ إليه."}},{"n":77,"reflection":{"text":"«ونصرناه من القوم الذين كذبوا بآياتنا إنهم كانوا قوم سوء فأغرقناهم أجمعين»، ونصرنا نوحًا على القومِ الذين كذّبوا بآياتنا، إنهم كانوا قومَ سوء، فأغرقناهم جميعًا؛ ففي هذا نصرُ الله لرسله على المكذّبين، وأنّ عاقبةَ التكذيبِ الهلاك؛ فثق بأنّ الله ينصر أهلَ الحقِّ على المكذّبين ولو بعد حين، واحذر التكذيبَ بآياتِ الله فإنه سببُ الهلاك.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الثقةُ بنصرِ الله لأهلِ الحقّ، والحذرُ من التكذيب."},"action":{"text":"ثق بأنّ الله ينصر رسله وأهلَ الحقِّ على المكذّبين ولو طال الأمد، واحذر التكذيبَ بشيءٍ من آياتِ الله فإنه سببُ الهلاك؛ فكن مع الحقِّ منصورًا، ولا تكن مع المكذّبين مغرورًا."}}]},{"title":"داودُ وسليمان: الحكمةُ وتسخيرُ الكون","range":[78,82],"theme":"تفهيمُ سليمانَ الحكمَ، وتسخيرُ الجبالِ والريحِ والشياطين","verses":[{"n":78,"reflection":{"text":"«وداود وسليمان إذ يحكمان في الحرث إذ نفشت فيه غنم القوم وكنا لحكمهم شاهدين»، واذكر داودَ وسليمانَ إذ يحكمان في زرعٍ رعته غنمُ قومٍ ليلًا فأفسدته، وكنا لحكمهم شاهدين مطّلعين؛ ففي هذا أنّ الله شاهدٌ على أحكامِ الحكّام، وأنّ القضاءَ بين الناسِ أمانةٌ عظيمة؛ فاعلم أنّ الله شاهدٌ على أحكامك ومعاملاتك، فتحرَّ العدلَ فيها، فالحاكمُ مسؤولٌ عن حكمه.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"استحضارُ شهادةِ الله على الأحكامِ وتحرّي العدل."},"action":{"text":"استحضر أنّ الله شاهدٌ مطّلعٌ على كلِّ حكمٍ تحكم به بين الناسِ وكلِّ معاملة، فتحرَّ العدلَ فيها ولا تجُر؛ فالقضاءُ والحكمُ بين الناسِ أمانةٌ يُسأل عنها العبد، فاتّقِ الله فيها."}},{"n":79,"reflection":{"text":"«ففهمناها سليمان وكلا آتينا حكما وعلما وسخرنا مع داود الجبال يسبحن والطير وكنا فاعلين»: ففهّمنا القضيةَ سليمانَ (فحكم بما هو أرفق)، وكلًّا من داودَ وسليمانَ آتينا حكمًا وعلمًا، وسخّرنا مع داودَ الجبالَ تسبّح معه والطير، وكنا فاعلين ذلك بقدرتنا؛ ففي هذا أنّ الفهمَ منحةٌ من الله يؤتيها من يشاء، وأنّ اجتهادَ المصيبِ لا يعيب المخطئ (فكلاهما أُوتي علمًا)، وأنّ الله يسخّر الكونَ لأوليائه؛ فاطلب الفهمَ من الله، ولا تعب المجتهدَ إذا اجتهد، وسبّح الله كما سبّحت الجبالُ مع داود.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["ففهمناها سليمان","الجبال يسبحن"],"heart_state":{"text":"طلبُ الفهمِ من الله، وتقديرُ اجتهادِ المجتهد."},"action":{"text":"اطلب من الله فهمًا سديدًا في دينك ودنياك، فالفهمُ منحةٌ منه؛ ولا تعب المجتهدَ المخطئَ ما دام قد بذل وسعه، فداودُ اجتهد وسليمانُ فُهِّم وكلاهما أُوتي علمًا؛ وسبّح الله بقلبٍ حاضرٍ كتسبيحِ الجبال."}},{"n":80,"reflection":{"text":"«وعلمناه صنعة لبوس لكم لتحصنكم من بأسكم فهل أنتم شاكرون»، وعلّمنا داودَ صناعةَ الدروعِ (اللبوس) لتقيكم في حروبكم، فهل أنتم شاكرون لهذه النعمة؟ ففي هذا امتنانُ الله بتعليمِ الصنائعِ النافعة، وأنّ العملَ باليدِ وتعلّمَ الصنعةِ من فضلِ الله يُشكَر؛ فاشكر الله على ما علّمك من صنعةٍ ونافعِ علم، وتعلّم ما ينفع الناسَ، فالصنعةُ النافعةُ نعمةٌ تُشكَر.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"شكرُ نعمةِ تعلّمِ الصنائعِ النافعةِ للناس."},"action":{"text":"اشكر الله على ما علّمك من صنعةٍ أو علمٍ نافع، واستعمله في نفعِ الناسِ وحمايتهم؛ فتعلّمُ الصنائعِ النافعةِ فضلٌ من الله يُشكَر بالعمل، كما علّم داودَ صنعةَ الدروعِ لحمايةِ الناس."}},{"n":81,"reflection":{"text":"«ولسليمان الريح عاصفة تجري بأمره إلى الأرض التي باركنا فيها وكنا بكل شيء عالمين»، وسخّرنا لسليمانَ الريحَ الشديدةَ تجري بأمره إلى أرضِ الشامِ المباركة، وكنا بكلِّ شيءٍ عالمين؛ ففي هذا عظمةُ ملكِ سليمانَ بتسخيرِ الريح، وأنّ الله على كلِّ شيءٍ قدير عالم؛ فتأمّل قدرةَ الله التي سخّرت الريحَ لعبده، واعلم أنّ الملكَ والتسخيرَ بيده، فاطلب فضله وحده.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"تأمّلُ قدرةِ الله في التسخير، وطلبُ فضلِه."},"action":{"text":"تأمّل قدرةَ الله التي سخّرت الريحَ العاصفةَ لسليمانَ تجري بأمره، فالملكُ والتسخيرُ كلُّه بيدِ الله؛ فاطلب الفضلَ والعطاءَ من الله وحده، واعلم أنّ ما بلغه أحدٌ من قدرةٍ فبتسخيرِ الله له."}},{"n":82,"reflection":{"text":"«ومن الشياطين من يغوصون له ويعملون عملا دون ذلك وكنا لهم حافظين»، وسخّرنا لسليمانَ من الشياطينِ من يغوصون في البحرِ يستخرجون له اللآلئ، ويعملون أعمالًا أخرى غيرَ ذلك، وكنا لهم حافظين من أن يخرجوا عن أمره؛ ففي هذا تمامُ تسخيرِ الله لسليمان حتى الشياطين، وأنّ حفظَ الله يضبط كلَّ مسخَّر؛ فاعلم أنّ الله يسخّر ما يشاء لمن يشاء ويحفظه، فكلُّ القوى بيده، فالجأ إليه وحده.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"العلمُ بشمولِ تسخيرِ الله وحفظِه لكلِّ القوى."},"action":{"text":"اعلم أنّ الله يسخّر ما يشاء من القوى لمن يشاء ويحفظها بأمره حتى الشياطين، فكلُّ شيءٍ بيده وتحت قهره؛ فالجأ إليه وحده، ولا تخف قوّةً من دونه، فالقوى كلُّها مسخّرةٌ محفوظةٌ بأمره."}}]},{"title":"أيوبُ وإخوانُه من الأنبياءِ الصابرين","range":[83,88],"theme":"دعاءُ أيوبَ وكشفُ ضرّه، وصبرُ إسماعيلَ وإدريسَ وذي الكفل، ونداءُ ذي النون","verses":[{"n":83,"reflection":{"text":"«وأيوب إذ نادى ربه أني مسني الضر وأنت أرحم الراحمين»، واذكر أيوبَ إذ دعا ربَّه بأدبٍ: أني أصابني الضرُّ (المرضُ وفقدُ الأهلِ والمال)، وأنت أرحمُ الراحمين؛ ففي هذا أدبُ أيوبَ في الدعاءِ (شكا لله لا اعتراضًا، وتوسّل برحمته)، وأنّ الصبرَ لا ينافي عرضَ الحاجةِ على الله؛ فإذا أصابك ضرٌّ فاشكه إلى الله بأدبٍ متوسّلًا برحمته، فذلك عينُ الصبرِ لا ينافيه.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["وأنت أرحم الراحمين"],"heart_state":{"text":"أدبُ الدعاءِ عند الضرِّ والتوسّلُ برحمةِ الله."},"action":{"text":"إذا مسّك ضرٌّ فاشكُه إلى الله وحده بأدبٍ، متوسّلًا برحمته «وأنت أرحم الراحمين»، لا معترضًا على قدره؛ فشكوى الحالِ إلى الله عبادةٌ وصبرٌ لا ينافيه، كما فعل أيوبُ الصابر."}},{"n":84,"reflection":{"text":"«فاستجبنا له فكشفنا ما به من ضر وآتيناه أهله ومثلهم معهم رحمة من عندنا وذكرى للعابدين»: فاستجبنا لأيوبَ فأزلنا ما به من مرضٍ وبلاء، وأعطيناه أهله ومثلهم معهم رحمةً منا وعبرةً للعابدين ليصبروا كما صبر؛ ففي هذا أنّ الصبرَ يعقبه الفرجُ والعوض، وأنّ في قصّةِ أيوبَ ذكرى للعابدين؛ فاصبر على البلاءِ واثقًا بأنّ الله يكشف الضرَّ ويعوّض الصابرين، واتّعظ بقصّةِ أيوبَ في الصبر.","source":"تفسير السعدي","grade":"ma'thur"},"names":["ذكرى للعابدين"],"heart_state":{"text":"الصبرُ على البلاءِ ثقةً بكشفِ الضرِّ والعوض."},"action":{"text":"اصبر على البلاءِ محتسبًا واثقًا بأنّ الله يكشف الضرَّ ويعوّض الصابرين خيرًا ممّا فقدوا؛ فأيوبُ صبر فكشف الله ضرّه وأعطاه أهله ومثلهم؛ فاجعل قصّته ذكرى تعينك على الصبرِ عند البلاء."}},{"n":85,"reflection":{"text":"«وإسماعيل وإدريس وذا الكفل كل من الصابرين»، واذكر إسماعيلَ وإدريسَ وذا الكفل، كلٌّ منهم من الصابرين على طاعةِ الله وعن معصيته وعلى أقداره؛ ففي هذا الثناءُ على الأنبياءِ بالصبر، وأنّ الصبرَ صفةُ المصطفَين؛ فتخلّق بالصبرِ الذي مدح الله به أنبياءه، فبالصبرِ تُنال المنازلُ العالية، وهو صفةُ الصالحين.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"التخلّقُ بالصبرِ الذي مُدِح به الأنبياء."},"action":{"text":"تخلّق بالصبرِ في طاعةِ الله وعن معصيته وعلى أقداره، فهو صفةٌ مدح الله بها أنبياءه؛ فبالصبرِ تُبلَغ أعلى المنازل، ويُنال رضا الله؛ فوطّن نفسك على الصبرِ في كلِّ حال، فهو مفتاحُ الفرج."}},{"n":86,"reflection":{"text":"«وأدخلناهم في رحمتنا إنهم من الصالحين»، وأدخلنا هؤلاء الأنبياءَ الصابرين في رحمتنا لأنهم من الصالحين؛ ففي هذا أنّ الصبرَ والصلاحَ سببُ دخولِ الرحمة، وأنّ عاقبةَ الصابرين الرحمة؛ فاجمع بين الصبرِ والصلاح، فبهما تدخل في رحمةِ الله؛ فالصالحون الصابرون هم أهلُ رحمةِ الله وكرامته.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الجمعُ بين الصبرِ والصلاحِ لدخولِ رحمةِ الله."},"action":{"text":"اجمع بين الصبرِ والصلاحِ في عملك، فبهما تدخل في رحمةِ الله كما أدخل أنبياءه الصابرين؛ فالصلاحُ عملٌ، والصبرُ عليه ثباتٌ، وبهما يُنال رضا الله ورحمتُه وكرامتُه."}},{"n":87,"reflection":{"text":"«وذا النون إذ ذهب مغاضبا فظن أن لن نقدر عليه فنادى في الظلمات أن لا إله إلا أنت سبحانك إني كنت من الظالمين»، واذكر يونسَ (ذا النون) إذ ذهب مغاضبًا لقومه، فظنّ أن لن نضيّق عليه، فناداه في ظلماتِ بطنِ الحوتِ والبحرِ والليل: لا إله إلا أنت سبحانك إني كنت من الظالمين (لنفسي)؛ ففي هذا فضلُ هذا الدعاءِ العظيمِ الجامعِ للتوحيدِ والتنزيهِ والاعترافِ بالذنب، وأنه سببُ الفرج؛ فادعُ بهذا الدعاءِ عند الكرب، واعترف بذنبك، فبالتوحيدِ والاعترافِ يأتي الفرج.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["لا إله إلا أنت سبحانك إني كنت من الظالمين"],"heart_state":{"text":"الدعاءُ بدعاءِ يونسَ والاعترافُ بالذنبِ عند الكرب."},"action":{"text":"الزم دعاءَ يونسَ عند الكربِ والهمّ «لا إله إلا أنت سبحانك إني كنت من الظالمين»، فما دعا به مكروبٌ إلا فرّج الله عنه؛ فوحّد الله ونزّهه واعترف بذنبك، فبذلك يأتي الفرجُ من عند الله."}},{"n":88,"reflection":{"text":"«فاستجبنا له ونجيناه من الغم وكذلك ننجي المؤمنين»: فاستجبنا ليونسَ ونجّيناه من الغمِّ الذي كان فيه، وكذلك ننجّي المؤمنين إذا دعونا كما دعا؛ ففي هذا أنّ الله ينجّي المؤمنين من كروبهم إذا لجؤوا إليه بالتوحيدِ والدعاء، وأنّ سنّتَه نجاةُ الداعين؛ فالجأ إلى الله بالدعاءِ والتوحيدِ عند كربك، واثقًا بأنه ينجّيك كما نجّى يونسَ والمؤمنين.","source":"تفسير السعدي","grade":"ma'thur"},"names":["وكذلك ننجي المؤمنين"],"heart_state":{"text":"الثقةُ بأنّ الله ينجّي المؤمنين الداعين من كروبهم."},"action":{"text":"الجأ إلى الله بالتوحيدِ والدعاءِ والاعترافِ عند كلِّ كربٍ وغمّ، واثقًا بأنّ سنّةَ الله نجاةُ المؤمنين الداعين؛ فكما نجّى يونسَ ينجّيك، فلا تيأس من فرجِ الله مهما اشتدّ الكرب."}}]},{"title":"زكريا ومريمُ، ووحدةُ الأمّة","range":[89,93],"theme":"دعاءُ زكريا والاستجابةُ له، ومريمُ آيةً، وأنّ الدينَ واحد","verses":[{"n":89,"reflection":{"text":"«وزكريا إذ نادى ربه رب لا تذرني فردا وأنت خير الوارثين»، واذكر زكريا إذ دعا ربَّه: ربِّ لا تتركني وحيدًا بلا ولدٍ يرثُ العلمَ والدين، وأنت خيرُ الباقين بعد خلقك؛ ففي هذا أدبُ زكريا في الدعاءِ وتفويضِه الأمرَ لله (وأنت خير الوارثين)، وحرصُه على من يخلفه في الدين؛ فادعُ الله بأدبٍ مفوّضًا الأمرَ إليه، واحرص على من يحمل الدينَ بعدك، وثق بأنه خيرُ الوارثين.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["وأنت خير الوارثين"],"heart_state":{"text":"الدعاءُ بأدبٍ مع تفويضِ الأمرِ لله."},"action":{"text":"ادعُ الله بحاجتك بأدبٍ مفوّضًا الأمرَ إليه راضيًا بحكمه «وأنت خير الوارثين»، واحرص على ذريّةٍ صالحةٍ تحمل الدينَ بعدك؛ فزكريا سأل الولدَ لحفظِ الدينِ ثم فوّض الأمرَ لربّه، فاقتدِ به."}},{"n":90,"reflection":{"text":"«فاستجبنا له ووهبنا له يحيى وأصلحنا له زوجه إنهم كانوا يسارعون في الخيرات ويدعوننا رغبا ورهبا وكانوا لنا خاشعين»: فاستجبنا لزكريا ووهبنا له يحيى وأصلحنا له زوجه (لتلد)، إنهم كانوا يسارعون في فعلِ الخيرات، ويدعوننا راغبين في رحمتنا راهبين من عذابنا، وكانوا لنا خاشعين متذلّلين؛ ففي هذا أنّ الاستجابةَ ثمرةُ المسارعةِ في الخيراتِ والدعاءِ رغبًا ورهبًا والخشوع؛ فسارِع في الخيرات، وادعُ الله بين الرجاءِ والخوف، والزم الخشوع، فتلك صفاتُ المستجابِ لهم.","source":"تفسير السعدي","grade":"ma'thur"},"names":["يسارعون في الخيرات","رغبا ورهبا"],"heart_state":{"text":"المسارعةُ في الخيرات، والدعاءُ رغبًا ورهبًا، والخشوع."},"action":{"text":"سارِع إلى فعلِ الخيراتِ ولا تؤخّرها، وادعُ الله راغبًا في رحمته راهبًا من عذابه، والزم الخشوعَ في عبادتك؛ فهذه صفاتُ من يستجيب الله لهم، فتخلّق بها لتكون من المسارعين المستجابِ دعاؤهم."}},{"n":91,"reflection":{"text":"«والتي أحصنت فرجها فنفخنا فيها من روحنا وجعلناها وابنها آية للعالمين»، واذكر مريمَ التي حفظت فرجها عن الحرام، فأمرنا جبريلَ أن ينفخ فيها فحملت بعيسى، وجعلناها وابنها عيسى علامةً للعالمين على قدرتنا؛ ففي هذا الثناءُ على مريمَ بالعفّة، وأنّ العفّةَ سببُ الكرامة، وأنّ خلقَ عيسى آيةٌ؛ فالزم العفّةَ وحفظَ الفرجِ عن الحرام، فبها الكرامةُ عند الله، وتأمّل آيةَ خلقِ عيسى دليلًا على قدرةِ الله.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["أحصنت فرجها","آية للعالمين"],"heart_state":{"text":"لزومُ العفّةِ وحفظِ الفرجِ سببًا للكرامة."},"action":{"text":"الزم العفّةَ وحفظَ فرجك عن الحرام، فبالعفّةِ الكرامةُ عند الله كما أكرم مريمَ العفيفة؛ وتأمّل في خلقِ عيسى بلا أبٍ آيةً على قدرةِ الله؛ فالطهارةُ والعفافُ من أعظمِ ما يتقرّب به العبدُ إلى ربّه."}},{"n":92,"reflection":{"text":"«إن هذه أمتكم أمة واحدة وأنا ربكم فاعبدون»: إنّ ملّتكم أيها الأنبياءُ والمؤمنون ملّةٌ واحدةٌ هي التوحيد، وأنا ربّكم وحدي فاعبدوني لا تشركوا بي؛ ففي هذا أنّ دينَ الأنبياءِ واحدٌ في أصله (التوحيد)، وأنّ الأمّةَ المؤمنةَ أمّةٌ واحدةٌ على عبادةِ الله؛ فاعتصم بدينِ التوحيدِ الذي هو دينُ الأنبياءِ جميعًا، والزم وحدةَ الأمّةِ على عبادةِ الله وحده.","source":"تفسير السعدي","grade":"ma'thur"},"names":["أمة واحدة","وأنا ربكم فاعبدون"],"heart_state":{"text":"الاعتصامُ بدينِ التوحيدِ ووحدةِ الأمّةِ عليه."},"action":{"text":"اعتصم بدينِ التوحيدِ الذي هو ملّةُ الأنبياءِ جميعًا، واعبد الله وحده لا شريك له؛ والزم وحدةَ الأمّةِ المؤمنةِ على هذا الأصل، فأصلُ الدينِ واحدٌ، والفرقةُ فيه بعدٌ عن هدي الرسل."}},{"n":93,"reflection":{"text":"«وتقطعوا أمرهم بينهم كل إلينا راجعون»، وتفرّق الناسُ في دينهم فرقًا وأحزابًا بعد أن كان واحدًا، وكلُّهم إلينا راجعون للحسابِ والجزاء؛ ففي هذا ذمُّ التفرّقِ في الدين، وأنّ المرجعَ إلى الله يجمعهم فيحاسبهم؛ فاحذر التفرّقَ في الدين، والزم الجماعةَ على الحقّ، واعلم أنّ الكلَّ راجعٌ إلى الله فيُجزى بعمله، فاعمل لذلك الرجوع.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من التفرّقِ في الدينِ ولزومُ الجماعةِ على الحقّ."},"action":{"text":"احذر التفرّقَ والاختلافَ في أصلِ الدين، والزم الجماعةَ على الحقّ والتوحيد؛ واستحضر أنّ الجميعَ راجعون إلى الله فيُحاسَبون، فاعمل لذلك الرجوعِ بالاعتصامِ بالحقِّ وترْكِ ما يفرّق الكلمة."}}]},{"title":"حفظُ السعيِ، وأشراطُ الساعة","range":[94,97],"theme":"أنّ سعيَ المؤمنِ لا يضيع، وخروجُ يأجوجَ ومأجوج، واقترابُ الوعد","verses":[{"n":94,"reflection":{"text":"«فمن يعمل من الصالحات وهو مؤمن فلا كفران لسعيه وإنا له كاتبون»: فمن يعمل شيئًا من الصالحاتِ وهو مؤمنٌ بالله، فلا يُجحَد سعيه ولا يضيع، وإنا نكتبه له ونجزيه عليه؛ ففي هذا أنّ العملَ الصالحَ مع الإيمانِ محفوظٌ مكتوبٌ لا يضيع، وأنّ الله لا يضيع أجرَ عامل؛ فاعمل الصالحاتِ مع الإيمانِ واثقًا بأنّ سعيك محفوظٌ مكتوبٌ عند الله، لا يضيع منه شيء.","source":"تفسير السعدي","grade":"ma'thur"},"names":["فلا كفران لسعيه"],"heart_state":{"text":"العملُ الصالحُ مع الإيمانِ والثقةُ بحفظِ السعي."},"action":{"text":"اجمع بين الإيمانِ والعملِ الصالح، واعمل واثقًا بأنّ الله يكتب سعيك ولا يضيّع منه ذرّة؛ فلا تحتقر عملًا صالحًا، ولا تيأس من قبوله، فكلُّه محفوظٌ مكتوبٌ يُجزى عليه."}},{"n":95,"reflection":{"text":"«وحرام على قرية أهلكناها أنهم لا يرجعون»، وممتنعٌ على أهلِ قريةٍ أهلكناها بذنوبهم أن يرجعوا إلى الدنيا ليتوبوا، أو أن يرجعوا عن كفرهم؛ ففي هذا أنّ الهلاكَ يقطع بابَ الرجوعِ والتوبة، وأنّ فرصةَ التوبةِ في الحياةِ لا بعدها؛ فاغتنم زمنَ الحياةِ للتوبةِ والرجوعِ إلى الله، فبعد الهلاكِ لا رجوع، والفرصةُ الآن.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"اغتنامُ زمنِ الحياةِ للتوبةِ قبل انقطاعِ الرجوع."},"action":{"text":"اغتنم مهلةَ الحياةِ للتوبةِ والرجوعِ إلى الله، فإنّ الهلاكَ يقطع بابَ الرجوعِ فلا توبةَ بعده؛ فلا تسوّف التوبةَ، فما دمت حيًّا فبابُ الرجوعِ مفتوح، وبعد الموتِ لا مردَّ."}},{"n":96,"reflection":{"text":"«حتى إذا فتحت يأجوج ومأجوج وهم من كل حدب ينسلون»: حتى إذا فُتِح سدُّ يأجوجَ ومأجوجَ فخرجوا، وهم من كلِّ مرتفعٍ يُسرِعون منتشرين في الأرض؛ ففي هذا الإخبارُ بأشراطِ الساعةِ الكبرى، وأنّ خروجَهم علامةٌ على قربها؛ فأيقن بأشراطِ الساعةِ التي أخبر بها الصادق، واستعدَّ لها بالعمل، فوقوعُها حقٌّ يقرّب الحساب.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"اليقينُ بأشراطِ الساعةِ والاستعدادُ لها."},"action":{"text":"أيقن بما أخبر به الله ورسوله من أشراطِ الساعةِ كخروجِ يأجوجَ ومأجوج، واستعدَّ ليومِ الحسابِ بالعملِ الصالح؛ فوقوعُ الأشراطِ حقٌّ يدلّ على قربِ الموعد، فلا تكن من الغافلين."}},{"n":97,"reflection":{"text":"«واقترب الوعد الحق فإذا هي شاخصة أبصار الذين كفروا يا ويلنا قد كنا في غفلة من هذا بل كنا ظالمين»، واقترب يومُ القيامةِ الحقّ، فإذا أبصارُ الكفارِ شاخصةٌ من الهول، يقولون: يا هلاكَنا قد كنا في غفلةٍ عن هذا اليوم، بل كنا ظالمين بكفرنا؛ ففي هذا اعترافُ الكفارِ بغفلتهم وظلمهم حين لا ينفع، وأنّ الغفلةَ عن الآخرةِ ظلم؛ فانفض الغفلةَ عن الآخرةِ اليوم، واعترف بتقصيرك وتب، قبل يومٍ يُعترَف فيه بلا فائدة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"طردُ الغفلةِ عن الآخرةِ والتوبةُ قبل فواتِ الأوان."},"action":{"text":"أيقظ قلبك من الغفلةِ عن الآخرةِ واستعدَّ لها، وتب من تقصيرك اليوم؛ فإنّ الكفارَ يعترفون يوم القيامةِ بغفلتهم وظلمهم حين لا ينفع الاعتراف، فلا تكن مثلهم، وبادر ما دمت في مهلة."}}]},{"title":"مصيرُ المعبوداتِ الباطلة، ونعيمُ المتّقين","range":[98,103],"theme":"أنّ الآلهةَ الباطلةَ حصبُ جهنم، وأنّ المتّقين مبعَدون عنها آمنون","verses":[{"n":98,"reflection":{"text":"«إنكم وما تعبدون من دون الله حصب جهنم أنتم لها واردون»: إنكم أيها المشركون وما تعبدون من دون الله من الأصنامِ وقودُ جهنم، أنتم داخلوها؛ ففي هذا خزيُ المشركين ومعبوداتهم الباطلةِ في النار، وأنّ العبادةَ الباطلةَ تجرّ لعذابِ المعبودِ والعابد؛ فلا تعبد ما يكون معك في النار، وأخلص العبادةَ لله الذي ينجّيك، فمعبودُ الباطلِ وعابدُه في النارِ سواء.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"إخلاصُ العبادةِ لله والحذرُ من عبادةِ الباطل."},"action":{"text":"أخلص عبادتك لله وحده، ولا تصرف شيئًا منها لمعبودٍ باطلٍ يكون معك وقودًا للنار؛ فعبادةُ الباطلِ خزيٌ وعذابٌ لعابده ومعبوده، والنجاةُ في توحيدِ الله الذي يُنجّي عابده."}},{"n":99,"reflection":{"text":"«لو كان هؤلاء آلهة ما وردوها وكل فيها خالدون»: لو كانت هذه المعبوداتُ آلهةً حقًّا ما دخلوا النار، لكنهم دخلوها، وكلٌّ من العابدِ والمعبودِ الباطلِ خالدون فيها؛ ففي هذا حجّةٌ على بطلانِ عبادتها بدخولها النار، وأنّ العاجزَ عن دفعِ النارِ عن نفسه ليس بإله؛ فلا تعبد من لا يدفع عن نفسه النار، وأخلص لله القادرِ الذي ينجّي من النار.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"إفرادُ الله بالعبادةِ لعجزِ المعبوداتِ الباطلة."},"action":{"text":"لا تعبد ولا ترجُ إلا الله، فالمعبوداتُ الباطلةُ عاجزةٌ لا تدفع النارَ عن نفسها فضلًا عن عابديها؛ فأخلص العبادةَ للقادرِ وحده الذي ينجّي من يشاء، فما سواه عاجزٌ لا يستحقُّ العبادة."}},{"n":100,"reflection":{"text":"«لهم فيها زفير وهم فيها لا يسمعون»: لأهلِ النارِ فيها زفيرٌ وصوتٌ شديدٌ من العذاب، وهم فيها لا يسمعون شيئًا ينفعهم لشدّةِ الهول؛ ففي هذا تصويرُ شدّةِ عذابِ النارِ وحرمانِ أهلها من كلِّ راحة؛ فاحذر النارَ التي هذا حالُ أهلها، واعمل على النجاةِ منها بالإيمانِ والطاعة، فعذابها شديدٌ لا يُطاق.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من النارِ والعملُ على النجاةِ منها."},"action":{"text":"احذر النارَ التي أهلها في زفيرٍ وعذابٍ لا يسمعون فيها ما ينفعهم، واعمل على النجاةِ منها بالإيمانِ والتوحيدِ والطاعةِ وترْكِ المعاصي؛ فمن عرف شدّةَ عذابها جدَّ في اجتنابِ أسبابه."}},{"n":101,"reflection":{"text":"«إن الذين سبقت لهم منا الحسنى أولئك عنها مبعدون»: إنّ الذين سبقت لهم من الله السعادةُ والبشرى بالجنّةِ (بإيمانهم وعملهم) أولئك عن النارِ مبعَدون؛ ففي هذا بشارةُ المؤمنين بالإبعادِ عن النار، وأنّ سابقةَ الحسنى بالإيمانِ والعمل؛ فاعمل بما يجعلك من أهلِ الحسنى المبعَدين عن النار، فالسعادةُ سابقةٌ لمن أخلص وعمل، فاجتهد لتكون منهم.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["سبقت لهم منا الحسنى"],"heart_state":{"text":"العملُ ليكون العبدُ من أهلِ الحسنى المبعَدين عن النار."},"action":{"text":"اعمل بالإيمانِ والصالحاتِ لتكون من أهلِ الحسنى الذين تُبعِدهم عن النارِ سابقةُ فضلِ الله؛ فالسعادةُ لمن أخلص لله وعمل صالحًا، فاجتهد في أسبابها لتنال البشرى بالإبعادِ عن النار."}},{"n":102,"reflection":{"text":"«لا يسمعون حسيسها وهم في ما اشتهت أنفسهم خالدون»: لا يسمع أهلُ الجنةِ صوتَ النارِ الخفيّ، وهم فيما تشتهيه أنفسهم من النعيمِ خالدون أبدًا؛ ففي هذا تمامُ أمنِ أهلِ الجنةِ من النار، ودوامُ نعيمهم بما يشتهون؛ فاعمل لجنّةٍ لا يُسمَع فيها حسيسُ النار، ونعيمها دائمٌ بما تشتهي النفوس، فاجعلها غايةَ سعيك.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"العملُ للجنّةِ ذاتِ الأمنِ والنعيمِ الدائم."},"action":{"text":"اعمل لجنّةٍ لا يسمع أهلها حسيسَ النار، وهم في نعيمٍ دائمٍ بما تشتهي أنفسهم؛ فاجعل الآخرةَ ونعيمها الباقي غايةَ سعيك، ووازِن بين نعيمها الدائمِ ولذّةِ الدنيا الفانية."}},{"n":103,"reflection":{"text":"«لا يحزنهم الفزع الأكبر وتتلقاهم الملائكة هذا يومكم الذي كنتم توعدون»: لا يحزن أهلَ الجنةِ الفزعُ الأكبرُ يوم القيامة، وتستقبلهم الملائكةُ مبشّرين: هذا يومكم الذي وُعِدتم فيه بالنعيم؛ ففي هذا أمنُ المؤمنين من فزعِ القيامةِ الأكبر، وتبشيرُ الملائكةِ لهم؛ فاعمل لتكون آمنًا يوم الفزعِ الأكبر، تستقبلك الملائكةُ بالبشرى، فالأمنُ يومئذٍ لأهلِ الإيمانِ والعمل.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["لا يحزنهم الفزع الأكبر"],"heart_state":{"text":"العملُ للأمنِ من الفزعِ الأكبرِ يومَ القيامة."},"action":{"text":"اعمل بالإيمانِ والطاعةِ لتكون ممّن لا يحزنهم الفزعُ الأكبرُ يوم القيامة، وتتلقّاهم الملائكةُ بالبشرى؛ فالأمنُ يومئذٍ لأهلِ التقوى والعمل، فاجتهد لتنال ذلك الأمنَ العظيم."}}]},{"title":"طيُّ السماء، ووراثةُ الصالحين، ورحمةُ الرسالة","range":[104,112],"theme":"إعادةُ الخلق، ووراثةُ الأرضِ للصالحين، وأنّ الرسولَ رحمة، والتفويضُ لله","verses":[{"n":104,"reflection":{"text":"«يوم نطوي السماء كطي السجل للكتب كما بدأنا أول خلق نعيده وعدا علينا إنا كنا فاعلين»: يوم نطوي السماءَ كما يُطوى الكتابُ على ما فيه، ونعيد الخلقَ كما بدأناهم أوّلَ مرّة، وعدًا حقًّا علينا، إنا فاعلون ما وعدنا؛ ففي هذا إثباتُ البعثِ بالقياسِ على الخلقِ الأول، وأنّ وعدَ الله واقعٌ لا محالة؛ فأيقن بالبعثِ الذي وعد الله به، فمن بدأ الخلقَ قادرٌ على إعادته، ووعدُه حقٌّ لا يتخلّف.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"اليقينُ بالبعثِ قياسًا على الخلقِ الأول."},"action":{"text":"أيقن بالبعثِ والإعادةِ يقينًا لا شكَّ فيه، فمن بدأ الخلقَ أوّلَ مرّةٍ قادرٌ على إعادته، ووعده حقٌّ لا يتخلّف؛ فاعمل لذلك اليومِ الذي تُطوى فيه السماءُ ويُعاد فيه الخلقُ للحساب."}},{"n":105,"reflection":{"text":"«ولقد كتبنا في الزبور من بعد الذكر أن الأرض يرثها عبادي الصالحون»، ولقد كتبنا في الزبورِ (أو الكتبِ المنزَّلة) بعد ما في اللوحِ المحفوظِ (الذكر) أنّ الأرضَ يرثها عبادي الصالحون بالتمكينِ في الدنيا وبالجنّةِ في الآخرة؛ ففي هذا وعدُ الله للصالحين بوراثةِ الأرضِ والتمكين، وأنّ العاقبةَ للصلاح؛ فاعمل بالصلاحِ لتكون من الوارثين، فوعدُ الله للصالحين بالتمكينِ والعاقبةِ حقٌّ، فاجتهد أن تكون منهم.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["يرثها عبادي الصالحون"],"heart_state":{"text":"العملُ بالصلاحِ رجاءَ وعدِ الله بالوراثةِ والتمكين."},"action":{"text":"اعمل بالصلاحِ في نفسك ومجتمعك، فقد وعد الله الصالحين بوراثةِ الأرضِ والتمكينِ فيها ونعيمِ الآخرة؛ فالعاقبةُ للصلاحِ لا للفساد، فاجتهد أن تكون من عبادِ الله الصالحين الوارثين."}},{"n":106,"reflection":{"text":"«إن في هذا لبلاغا لقوم عابدين»: إنّ في هذا القرآنِ وما فيه من المواعظِ لكفايةً وبلاغًا لقومٍ عابدين لله ينتفعون به؛ ففي هذا أنّ المنتفعَ بالقرآنِ أهلُ العبادة، وأنّ فيه كفايةً لمن أراد الهدى؛ فكن من العابدين الذين ينتفعون بالقرآنِ ويتّعظون به، فهو بلاغٌ وكفايةٌ لمن عبد الله وأقبل عليه.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"أن يكون العبدُ من العابدين المنتفعين بالقرآن."},"action":{"text":"كن من العابدين الذين ينتفعون بالقرآنِ ويجدون فيه بلاغًا وكفاية، بأن تعبد الله وتُقبِل على كتابه متدبّرًا عاملًا؛ فالقرآنُ كفايةٌ وعظةٌ لمن أراد الهدى وعبد الله حقَّ عبادته."}},{"n":107,"reflection":{"text":"«وما أرسلناك إلا رحمة للعالمين»، وما أرسلناك يا محمد إلا رحمةً للعالمين كلِّهم (فبعثتُه رحمةٌ للمؤمنِ والكافرِ والإنسِ والجنّ، هدايةً ونجاةً)؛ ففي هذا أنّ رسالةَ النبيِّ ﷺ رحمةٌ عامّة، وأنّ اتّباعه هو تحقيقُ هذه الرحمة؛ فاشكر الله على نعمةِ هذا الرسولِ الرحمة، واتبع هديه لتنال الرحمةَ التي أُرسِل بها، فالسعادةُ في اتّباعه.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["رحمة للعالمين"],"heart_state":{"text":"شكرُ نعمةِ الرسولِ الرحمة، واتّباعُ هديه."},"action":{"text":"اشكر الله على أعظمِ نعمةٍ: بعثةِ محمدٍ ﷺ رحمةً للعالمين، واتبع هديه وسنّته لتنال الرحمةَ التي أُرسِل بها؛ فمن اتّبعه سعد في الدنيا والآخرة، ومن أعرض حُرِم رحمتها."}},{"n":108,"reflection":{"text":"«قل إنما يوحى إلي أنما إلهكم إله واحد فهل أنتم مسلمون»: قل يا محمد: إنما يوحى إليّ أنّ معبودكم إلهٌ واحدٌ لا شريك له، فهل أنتم منقادون مستسلمون لتوحيده؟ ففي هذا أنّ زبدةَ الوحيِ التوحيد، وأنّ المطلوبَ الإسلامُ والانقيادُ له؛ فاستسلم لتوحيدِ الله وانقد له بقلبك وجوارحك، فذلك خلاصةُ الرسالةِ ومقصودُها.","source":"تفسير السعدي","grade":"ma'thur"},"names":["إلهكم إله واحد"],"heart_state":{"text":"الاستسلامُ لتوحيدِ الله والانقيادُ له."},"action":{"text":"استسلم لله بالتوحيدِ وانقد له بقلبك وجوارحك، فذلك خلاصةُ ما أُوحِي إلى الرسل: «إلهكم إله واحد»؛ فحقّق الإسلامَ بإفرادِ الله بالعبادةِ والطاعة، فالإسلامُ لله هو مقصودُ الرسالة."}},{"n":109,"reflection":{"text":"«فإن تولوا فقل آذنتكم على سواء وإن أدري أقريب أم بعيد ما توعدون»: فإن أعرضوا عن التوحيدِ فقل: أعلمتكم بما أُرسِلت به إعلامًا مستويًا نحن فيه سواء، وما أدري أقريبٌ أم بعيدٌ ما توعدون به من العذابِ أو القيامة؛ ففي هذا إعذارٌ وإنذار، وردُّ علمِ الغيبِ إلى الله؛ فبلّغ الحقَّ لتُعذَر، وردَّ علمَ ما غاب إلى الله، ولا تدّعِ علمَ الغيب، فوظيفتُك البلاغُ والإنذار.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"إبلاغُ الحقِّ للإعذار، وردُّ علمِ الغيبِ إلى الله."},"action":{"text":"بلّغ الحقَّ للناسِ بوضوحٍ لتُعذَر أمام الله، ولا تحزن على إعراضهم فوظيفتُك البلاغُ لا الهداية؛ وردَّ علمَ ما غاب من موعدِ الجزاءِ إلى الله، ولا تدّعِ علمَ ما استأثر الله بعلمه."}},{"n":110,"reflection":{"text":"«إنه يعلم الجهر من القول ويعلم ما تكتمون»: إنّ الله يعلم ما تجهرون به من القولِ وما تخفونه في صدوركم؛ ففي هذا إحاطةُ علمِ الله بالظاهرِ والباطن، وأنه لا يخفى عليه شيء؛ فراقب الله في جهرك وسرّك، واحذر أن تُبطِن ما يكره، فهو يعلم ما تُظهِر وما تُخفي، فاستوِ في مراقبته سرًّا وعلنًا.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"مراقبةُ الله في الجهرِ والسرِّ لإحاطةِ علمه."},"action":{"text":"راقب الله في جهرِ قولك وسرِّه، وفي ظاهرِ عملك وباطنِ قلبك، فهو يعلم ما تُظهِر وما تكتم؛ فطهّر باطنك كما تطهّر ظاهرك، واستوِ في مراقبته في السرِّ والعلن، فلا يخفى عليه شيء."}},{"n":111,"reflection":{"text":"«وإن أدري لعله فتنة لكم ومتاع إلى حين»، وما أدري لعلّ تأخيرَ العذابِ عنكم اختبارٌ لكم ومتاعٌ تُمتَّعون به إلى أجلٍ مقدَّر؛ ففي هذا أنّ الإمهالَ قد يكون فتنةً واستدراجًا، وأنّ متاعَ الدنيا إلى حين؛ فلا تغترَّ بتأخّرِ العقوبةِ وسعةِ المتاع، فقد يكون فتنةً واستدراجًا، ومتاعُ الدنيا زائلٌ إلى أجل.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من أن يكون الإمهالُ فتنةً واستدراجًا."},"action":{"text":"لا تغترَّ بتأخّرِ العقوبةِ عنك أو سعةِ متاعك، فقد يكون ذلك فتنةً واستدراجًا، ومتاعُ الدنيا زائلٌ إلى حين؛ فحاسب نفسك، ولا تجعل النعمةَ حجّةً على الغفلة، بل اشكرها بالطاعة."}},{"n":112,"reflection":{"text":"«قال رب احكم بالحق وربنا الرحمن المستعان على ما تصفون»: قال النبيُّ ﷺ: ربِّ احكم بيني وبين المكذّبين بالحقّ، وربّنا الرحمنُ هو المُستعانُ على ما تصفونه به من الكذبِ والباطل؛ ففي هذا تفويضُ النبيِّ ﷺ الأمرَ لله والاستعانةُ به، وأنّ الرحمنَ خيرُ معينٍ على أذى المبطلين؛ فوّض أمرك إلى الله واستعن به على ما يصفك به المبطلون، فهو الرحمنُ المُستعانُ الذي يكفيك ويحكم بالحقّ.","source":"تفسير السعدي","grade":"ma'thur"},"names":["الرحمن المستعان"],"heart_state":{"text":"تفويضُ الأمرِ إلى الله والاستعانةُ به على أذى المبطلين."},"action":{"text":"فوّض أمرك إلى الله واطلب منه أن يحكم بالحقِّ بينك وبين خصومك، واستعن به وحده على ما يصفك به المبطلون ويؤذونك؛ فالرحمنُ خيرُ معينٍ لمن لجأ إليه، وحسبك أنه المُستعان."}}]}],"coverage":{"covered":112,"total":112}};
